/* Market reports, one array per year. Read by build.js to generate /blog/ and the
   year pages. Deliberately NOT loaded by index.html - it was 179 KB of the
   homepage payload and the browser never needed it. */
/* ===========================================================
   INSIGHTS — market observations per year
=========================================================== */
const BLOG = {
  1990: [
    {date:"September 26, 2026", body:"The <b>1990 Topps #336</b> PSA 10 sold three times at exactly $1,300, one of them a 43-bid auction, lifting the flagship rookie from $1,250 to <span class='up'>$1,300</span>. Its <b>Tiffany</b> version jumped in PSA 9 from $430 to <span class='up'>$500</span>. <b>1990 Topps Major League Debut #46</b> PSA 10 climbed from $267 to <span class='up'>$301</span> across four sales. Cooling off: <b>Upper Deck #156</b> PSA 10 from $278 to <span class='down'>$255</span> on four sales, <b>Topps Big #250</b> from $330 to <span class='down'>$274</span>, and <b>Bowman Tiffany #481</b> PSA 9 from $275 to <span class='down'>$202</span>."},
    {date:"September 20, 2026", body:"The <b>1990 Bowman #481</b> PSA 10 climbed from $142 to <span class='up'>$224</span> (up 58%) while its Tiffany version moved from $213 to <span class='up'>$275</span> in PSA 9. <b>1990 Upper Deck #156</b> PSA 10 was the busiest card of the week with seven sales, three of them auctions of 25 or more bids, and settled from $287 to <span class='down'>$278</span>. A PSA 10 of the <b>1990 Leaf #245</b> sold for <span class='up'>$500</span>, up from $345 (up 45%), behind only the Topps and O-Pee-Chee #336 among 1990 base-card gems."},
    {date:"September 13, 2026", body:"The <b>1990 Topps #336</b> PSA 10 sold twice, $1,350 after 10 bids and $1,150 after 22, and eased from $1,460 to <span class='down'>$1,250</span>; its Tiffany version in PSA 9 came down from $700 to <span class='down'>$430</span>. A <b>1990 Topps Toys R Us Rookies #13</b> PSA 10 drew 135 bids, the most on any card in the guide this week, and sold for $816 to hold the grade at <span class='down'>$819</span>. <b>1990 Upper Deck #156</b> PSA 10 firmed from $272 to <span class='up'>$287</span> on a $300 sale and a 25-bid auction at $274."},
    {date:"September 9, 2026", body:"The <b>1990 Upper Deck #156</b> PSA 10 climbed from $241 to <span class='up'>$272</span> across five sales, the busiest 1990 card of the week. A 32-bid auction took the <b>1990 Topps Major League Debut #46</b> PSA 10 the other way, down from $330 to <span class='down'>$277</span>. The <b>Toys &#39;R&#39; Us Rookies #13</b> PSA 9 firmed from $125 to <span class='up'>$134</span> across four sales, three of them contested auctions."},
    {date:"September 6, 2026", body:"The <b>1990 Topps Toys 'R' Us Rookies #13</b> PSA 10 climbed from $631 to <span class='up'>$822</span> across five sales, one of them a 99-bid auction that closed at $911. <b>1990 Topps Tiffany #336</b> PSA 9 jumped from $371 to <span class='up'>$700</span> (up 89%), pulling far clear of the base #336, whose PSA 9 still trades at $45. <b>1990 Fleer Soaring Stars #6</b> PSA 9 nearly doubled from $125 to <span class='up'>$229</span>."},
    {date:"August 28, 2026", body:"<b>1990 Leaf #245</b> PSA 10 doubled from $225 to <span class='up'>$450</span> &mdash; the guide's key '90 rookie insert is running hot again. <b>1990 Topps #336</b> PSA 10 pushed to a new high, $1,349 to <span class='up'>$1,450</span>. <b>1990 Upper Deck #156</b> PSA 10 gave back over half its value, from $304 to <span class='down'>$140</span>, on the first sale since its August spike."},
    {date:"August 21, 2026", body:"<b>1990 Leaf #245</b> PSA 10 pulled back sharply from $460 to <span class='down'>$225</span> (down 51%) on a single sale &mdash; a sharp reversal on the guide's key '90 rookie insert. <b>1990 Donruss #365</b> PSA 10 climbed from $165 to <span class='up'>$208</span> (up 26%) across five sales. <b>1990 Upper Deck #156</b> gets its first raw price, $160."},
    {date:"August 9, 2026", body:"<b>1990 Upper Deck #156</b> PSA 10 jumped from $150 to <span class='up'>$304</span> (up 103%) on a 25-bid auction. <b>1990 Score #560</b> PSA 10 eased back from $175 to <span class='down'>$138</span>, and <b>1990 Donruss Learning Series #8</b> softened across the board &mdash; raw from $30 to <span class='down'>$25</span>, PSA 8 from $57 to <span class='down'>$37</span>."},
    {date:"August 7, 2026", body:"<b>1990 Leaf #245</b> PSA 10 climbed from $280 to <span class='up'>$460</span> (up 64%). <b>1990 Score #560</b> PSA 10 rose from $110 to <span class='up'>$175</span> (up 59%). <b>1990 Donruss Learning Series #8</b> got its first-ever sale, a raw copy at $30."},
    {date:"August 3, 2026", body:"<b>1990 Donruss Diamond Kings #4</b> PSA 9 jumped from $32 to <span class='up'>$76</span> (up 138%) on an 11-bid auction. <b>1990 Toys \"R\" Us Rookies #13</b> PSA 10 climbed from $500 to <span class='up'>$631</span>, while its PSA 9 tier eased back from $187 to <span class='down'>$150</span>. <b>1990 Upper Deck #156</b> and <b>1990 Score #560</b> PSA 10s both softened, to <span class='down'>$125</span> and <span class='down'>$110</span>."},
    {date:"July 31, 2026", body:"<b>1990 Toys \"R\" Us Rookies #13</b> PSA 9 jumped from $114 to <span class='up'>$187</span> (up 64%) on a 44-bid auction &mdash; this card has swung hard all year, and buyers showed up to chase it again. <b>1990 Soaring Stars #6</b> joins the guide for the first time at $125 PSA 9, filling in one of the last untracked 1990 Fleer inserts."},
    {date:"July 25, 2026", body:"Graded rookies across the board pushed to new highs. <b>1990 Fleer #513</b> led the way &mdash; PSA 10 up from $109 to <span class='up'>$135</span> and PSA 9 more than doubled from $12 to <span class='up'>$30</span>. <b>1990 Bowman #481</b> PSA 10 climbed from $126 to <span class='up'>$150</span> and PSA 9 from $24 to <span class='up'>$30</span>, while <b>1990 Bowman Tiffany #481</b> PSA 10 firmed from $500 to <span class='up'>$525</span>. <b>1990 Donruss #365</b> PSA 10 jumped from $146 to <span class='up'>$170</span>, and <b>1990 Major League Debut #46</b> PSA 10 from $265 to <span class='up'>$295</span> with PSA 9 up from $38 to <span class='up'>$40</span>. <b>1990 Upper Deck #156</b> PSA 9 climbed from $20 to <span class='up'>$30</span>, and <b>1990 Toys R Us Rookies #13</b> PSA 9 edged from $111 to <span class='up'>$114</span> on a 26-bid auction. The base <b>1990 Topps #336</b> PSA 9 jumped from $34 to <span class='up'>$50</span> across a cluster of sales."},
    {date:"July 23, 2026", body:"The <b>1990 Topps #336</b> PSA 10 pushed to a new high, from $1,365 to <span class='up'>$1,400</span> in a 24-bid auction. <b>1990 Fleer #513</b> PSA 10 climbed from $77 to <span class='up'>$109</span> (up 41%) and <b>1990 Toys R Us Rookies #13</b> PSA 9 jumped from $77 to <span class='up'>$111</span> (up 44%), while <b>1990 Leaf #245</b> PSA 10 pulled back from $404 to <span class='down'>$260</span> (down 36%) and <b>1990 Upper Deck #156</b> PSA 10 eased from $164 to <span class='down'>$130</span> (down 21%)."},
    {date:"July 15, 2026", body:"The <b>1990 Leaf #245</b> PSA 10 climbed from $257 to <span class='up'>$404</span> (up 57%) in a 38-bid auction. <b>1990 Major League Debut #46</b> PSA 10 rose from $228 to <span class='up'>$290</span> with 26 bids, <b>1990 Score #560</b> PSA 10 from $96 to <span class='up'>$135</span> (up 41%), and <b>1990 Upper Deck #156</b> PSA 10 from $150 to <span class='up'>$164</span>. <b>1990 O-Pee-Chee #336</b> PSA 9 moved from $120 to <span class='up'>$134</span>, <b>1990 Donruss #365</b> PSA 10 from $138 to <span class='up'>$146</span>, and <b>1990 Best of the AL #1</b> raw from $45 to <span class='up'>$80</span>. A <b>1990 Fleer All-Stars #14</b> PSA 10 sold for $190. Giving back: <b>1990 Topps Tiffany #336</b> raw from $201 to <span class='down'>$93</span> (down 54%) at auction and <b>1990 Toys R Us Rookies #13</b> PSA 9 from $175 to <span class='down'>$77</span> (down 56%) on two same-day sales. The <b>1990 Bowman Tiffany</b> PSA 10 sold at exactly $500 again."},
    {date:"July 10, 2026", body:"Raw cards led the day. A <b>1990 Topps #336</b> sold ungraded for <span class='up'>$40</span> at auction — above the $33-$34 that two PSA 9 copies brought the same day, which pulled the PSA 9 from $40 to <span class='down'>$34</span>. The <b>1990 Topps Tiffany #336</b> raw more than doubled from $90 to <span class='up'>$201</span>. <b>1990 Upper Deck #156</b> PSA 10 bounced from $131 to <span class='up'>$150</span> a day after its last sale, while <b>1990 Donruss #365</b> PSA 10 eased from $145 to <span class='down'>$138</span> at auction with 25 bids. <b>1990 Major League Debut #46</b> split: PSA 8 up from $20 to <span class='up'>$35</span>, PSA 9 down from $42 to <span class='down'>$38</span>. First raw prices landed on <b>1990 Diamond Kings #4</b> at $50 and <b>1990 Best of the AL #1</b> at $45, and a $1,350 sale backed up yesterday's $1,365 on the <b>1990 Topps #336</b> PSA 10."},
    {date:"July 9, 2026", body:"The <b>1990 Topps #336</b> PSA 10 pushed from $1,100 to <span class='up'>$1,365</span> at auction with 18 bids — the strongest sale on the flagship rookie in months. <b>1990 Glossy Rookies #11</b> PSA 10 jumped from $380 to <span class='up'>$650</span> on back-to-back sales at $725 and $633. <b>1990 Donruss Best of the AL</b> PSA 9 nearly doubled from $51 to <span class='up'>$99</span>, <b>1990 Bowman Tiffany</b> PSA 10 rose from $466 to <span class='up'>$500</span>, <b>1990 Diamond Kings</b> PSA 10 moved from $860 to <span class='up'>$900</span>, and <b>1990 Topps Tiffany</b> PSA 9 climbed from $380 to <span class='up'>$400</span>. The base tier cooled underneath: <b>1990 Donruss #365</b> PSA 10 fell from $203 to <span class='down'>$145</span> on two sales, <b>1990 O-Pee-Chee #336</b> PSA 9 slid from $148 to <span class='down'>$120</span>, <b>1990 Major League Debut #46</b> PSA 10 dropped from $270 to <span class='down'>$228</span> at auction a day after a $307 sale, and <b>1990 Upper Deck #156</b> PSA 10 eased from $140 to <span class='down'>$131</span>. The <b>1990 Toys R Us Rookies #13</b> PSA 10 sold at exactly $510 again — three confirmations in ten days."},
    {date:"June 29, 2026", body:"The Toys R Us PSA 10 that dropped to $240 five days ago just sold twice in the same day for over $500. Back-to-back auctions landing at <span class='up'>$510</span> — the June 24 sale was the outlier, not the new floor. And the PSA 9 backed it up: tripled from $60 to <span class='up'>$175</span>, which tells you this isn't one fluke sale. The whole 1990 base market moved with it. The <b>1990 Topps #336</b> PSA 10 is holding above $1,100 with multiple confirmations. The <b>1990 Donruss #365</b> PSA 10 crossed $200 for the first time — condition sensitive cards are finally getting condition-sensitive prices. <b>1990 Tiffany #336</b> PSA 9 hit $380 and raw Tiffany copies are clearing $90. If you've been sitting on 1990 base in high grade, the market is catching up to you."},
    {date:"June 24, 2026", body:"<b>1990 Toys R Us Rookies #13</b> PSA 10 dropped sharply from $450 to <span class='down'>$240</span> — previous data may have been stale. <b>1990 Fleer #513</b> PSA 10 moved the other direction, climbing from $75 to <span class='up'>$96</span>. <b>1990 Donruss Diamond Kings</b> PSA 9 softened from $40 to <span class='down'>$32</span>. The junk wax base market continues to recalibrate — old prices are being tested by fresh sales data."},
    {date:"June 23, 2026", body:"<b>1990 Toys R Us Rookies #13</b> climbing — PSA 8 moved from $23 to <span class='up'>$30</span> and PSA 9 from $44 to <span class='up'>$60</span>. <b>1990 Donruss #365</b> PSA 10 ticked up from $120 to <span class='up'>$131</span> at auction with 20 bids — condition-sensitive cards are rewarding patience. <b>1990 Topps #336</b> PSA 8 rebounded from $11 to <span class='up'>$24</span> while PSA 9 softened from $45 to <span class='down'>$36</span> — buyers shifting to the more affordable grade. Added <b>1990 Bowman Tiffany</b> PSA 9 at $150."},
    {date:"June 22, 2026", body:"<b>1990 Leaf #245</b> PSA 9 jumped from $20 to <span class='up'>$30</span> — a 50% move on the card most collectors consider the best base Griffey of 1990. <b>1990 Major League Debut</b> PSA 9 dropped from $60 to <span class='down'>$42</span>. Added <b>1990 Bowman Tiffany</b> PSA 8 at $70 — first PSA 8 data point on that card."},
    {date:"June 21, 2026", body:"Junk wax base continues to soften. <b>1990 Topps #336</b> PSA 8 dropped from $16 to <span class='down'>$11</span>, and <b>1990 Score #560</b> PSA 10 slid from $109 to <span class='down'>$96</span>. The <b>1990 Major League Debut</b> PSA 8 also dipped from $23 to <span class='down'>$20</span>. Meanwhile, <b>1990 Leaf #245</b> raw copies are going for just $4 — that 10x multiplier to PSA 10 ($219) makes raw copies a gamble worth taking."}
  ],
  1991: [
    {date:"September 26, 2026", body:"A <b>1991 Topps Desert Shield #790</b> PSA 8 sold for <span class='up'>$1,300</span>, up from $1,000 (up 30%). <b>1991 Score Dream Team #892</b> PSA 10 was the busiest card of the year with seven sales between $145 and $210, lifting the grade from $155 to <span class='up'>$189</span>. <b>1991 Score Rifleman #697</b> PSA 10 traded six times and firmed from $104 to <span class='up'>$114</span>, while <b>Topps Tiffany All-Star #392</b> PSA 9 eased from $153 to <span class='down'>$132</span> on two sales."},
    {date:"September 20, 2026", body:"The <b>1991 Topps Desert Shield All-Star #392</b> PSA 9 sold twice in contested auctions, $760 after 39 bids and $711 after 37, and came down from $1,000 to <span class='down'>$711</span>, still above the $611 its PSA 8 brought earlier this month. <b>1991 Stadium Club #270</b> PSA 9 was the busiest 1991 card with five sales and climbed from $46 to <span class='up'>$81</span> (up 76%), while <b>1991 Score All-Star #396</b> PSA 9 moved from $32 to <span class='up'>$50</span> on four sales. <b>1991 Score #2</b> PSA 10 rose from $120 to <span class='up'>$158</span> in a 14-bid auction."},
    {date:"September 13, 2026", body:"The <b>1991 Topps Desert Shield #790</b> PSA 9 sold twice in five days, $2,469 after 41 bids and $2,551 after 30, and moved from $2,400 to <span class='up'>$2,510</span>; a raw copy went the other way, from $588 to <span class='down'>$350</span>. <b>1991 Score Dream Team #892</b> PSA 10 was the busiest gem of the year with seven sales between $135 and $203, settling from $170 to <span class='down'>$165</span>. <b>1991 Fleer #450</b> PSA 10 came down from $190 to <span class='down'>$130</span> on two sales, one of them a 23-bid auction."},
    {date:"September 9, 2026", body:"<b>1991 Ultra #336</b> PSA 10 nearly doubled off a 39-bid auction, from $132 to <span class='up'>$238</span> (up 80%). <b>1991 Fleer All-Stars #7</b> PSA 9 climbed from $121 to <span class='up'>$200</span> (up 65%), and the <b>1991 Upper Deck #555</b> PSA 10 from $90 to <span class='up'>$131</span> across five sales. The <b>Topps Desert Shield #790</b> PSA 9 eased from $2,500 to <span class='down'>$2,400</span>."},
    {date:"September 6, 2026", body:"A PSA 9 of the <b>1991 Topps Desert Shield #790</b> sold for <span class='up'>$2,500</span>, up from $2,400, and ungraded copies of the same card changed hands twice between $525 and $650. The <b>Desert Shield All-Star #392</b> PSA 8 followed it up, climbing from $550 to <span class='up'>$611</span> in a 29-bid auction. <b>1991 Score Dream Team #892</b> PSA 10 firmed from $151 to <span class='up'>$163</span> across four sales, a card that was bringing $125 earlier in August."},
    {date:"August 27, 2026", body:"<b>1991 Score The Franchise #858</b> PSA 10 jumped from $155 to <span class='up'>$279</span> (up 80%). <b>1991 Topps Tiffany All-Star #392</b> PSA 10 climbed from $423 to <span class='up'>$534</span>. <b>1991 Desert Shield All-Star #392</b> raw eased from $413 to <span class='down'>$228</span> on a single lower auction."},
    {date:"August 21, 2026", body:"<b>1991 Desert Shield #790</b> PSA 9 climbed from $1,900 to <span class='up'>$2,400</span> (up 26%), still the priciest card in the '91 guide by a wide margin. <b>1991 Score All-Star #396</b> PSA 10 firmed from $158 to <span class='up'>$186</span> (up 18%) across six separate sales. <b>1991 Desert Shield All-Star #392</b> gets its first raw price, $413."},
    {date:"August 9, 2026", body:"<b>1991 Score All-Star #396</b> PSA 10 climbed from $137 to <span class='up'>$158</span>, with its PSA 9 tier also firming from $27 to <span class='up'>$32</span>. <b>1991 Topps Base #790</b> PSA 9 pulled back from $25 to <span class='down'>$18</span>, while <b>1991 Donruss All-Stars #49</b> PSA 10 eased from $90 to <span class='down'>$75</span>."},
    {date:"July 31, 2026", body:"<b>1991 Fleer #450</b> PSA 10 climbed from $80 to <span class='up'>$119</span> (up 49%), a real break from the low-$80s it's traded at most of this year. <b>1991 Elite Series #13</b> raw eased from $515 to <span class='down'>$440</span>, but a /10,000 print run still commands more unraded than most 1991 Griffeys do in PSA 10 &mdash; the scarcity keeps a floor under it even on a down week."},
    {date:"July 25, 2026", body:"<b>1991 Desert Shield All-Star #392</b> PSA 9 sold for $1,000, up from $900. <b>1991 Score Dream Team #892</b> moved on two fronts — PSA 10 from $100 to <span class='up'>$125</span> and raw copies up to <span class='up'>$23</span>. <b>1991 Donruss MVP #392</b> PSA 10 sold for $100 and <b>1991 Topps #790</b> PSA 9 climbed from $18 to <span class='up'>$25</span>."},
    {date:"July 15, 2026", body:"<b>1991 Upper Deck #555</b> PSA 10 jumped from $59 to <span class='up'>$90</span> (up 53%) in a 17-bid auction, and the <b>1991 Score Rifleman #697</b> rose at both grades — PSA 10 from $85 to <span class='up'>$87</span> and PSA 9 from $17 to <span class='up'>$23</span>. <b>1991 Score All-Star #396</b> PSA 10 moved from $136 to <span class='up'>$140</span> on two same-day sales, and <b>1991 Final Edition #79F</b> PSA 10 from $36 to <span class='up'>$43</span>. A <b>1991 Donruss MVP #392</b> PSA 10 sold for $95, a <b>1991 Score #2</b> PSA 10 for $100, and a <b>1991 Topps All-Star #392</b> PSA 9 for $27. Cooling underneath: <b>1991 Bowman #246</b> PSA 10 from $150 to <span class='down'>$110</span> (down 27%), <b>1991 Dream Team #892</b> PSA 10 from $115 to <span class='down'>$100</span>, <b>1991 Donruss All-Stars #49</b> PSA 10 from $100 to <span class='down'>$90</span>, and <b>1991 Stadium Club #270</b> PSA 9 from $50 to <span class='down'>$46</span>."},
    {date:"July 10, 2026", body:"The <b>1991 Stadium Club #270</b> PSA 10 broke out: a 27-bid auction hit $477 and a $500 sale followed the next day, moving the card from $400 to <span class='up'>$490</span>. The PSA 9 went with it, from $30 to <span class='up'>$50</span>. <b>1991 Bowman #246</b> PSA 10 jumped from $85 to <span class='up'>$150</span>, and <b>1991 Topps All-Star #392</b> PSA 10 edged from $70 to <span class='up'>$78</span> on three sales. First PSA 10 prices: <b>1991 Ultra Gold</b> at $286 and <b>1991 Score Rifleman #697</b> at $85. Desert Shield held its marks — the <b>1991 #790</b> PSA 8 sold at $999 and the <b>1991 All-Star #392</b> PSA 9 at $900."},
    {date:"July 9, 2026", body:"Desert Shield day. The <b>1991 #790</b> PSA 10 hit <span class='up'>$4,500</span>, the PSA 8 eased to <span class='down'>$999</span>, and the <b>1991 Desert Shield All-Star #392</b> PSA 9 climbed to <span class='up'>$900</span> — military-only distribution keeps supply low. First PSA 10 data on the <b>1991 O-Pee-Chee #790</b> landed at $483 at auction with 30 bids, and the <b>1991 O-Pee-Chee Premier #56</b> PSA 10 jumped from $144 to <span class='up'>$200</span>. Underneath, the whole '91 tier moved up on July 7-8 results: <b>1991 Topps #790</b> PSA 10 from $150 to <span class='up'>$156</span>, <b>1991 Score All-Star #396</b> from $130 to <span class='up'>$136</span>, <b>1991 Dream Team #892</b> from $95 to <span class='up'>$115</span> on three sales, <b>1991 Donruss #77</b> from $92 to <span class='up'>$103</span>, <b>1991 Leaf #372</b> from $95 to <span class='up'>$100</span> with 19 bids, and <b>1991 Donruss All-Stars #49</b> from $80 to <span class='up'>$100</span>."},
    {date:"June 29, 2026", body:"Quietly productive day in 1991. The <b>1991 O-Pee-Chee Premier #56</b> has always been the harder-to-find Canadian cousin of the Upper Deck base — crisp design, limited distribution. First PSA 10 data landed at <span class='up'>$144</span>, which feels right given how rarely gem copies show up. The Score inserts are also finding a floor: <b>1991 All-Star #396</b> PSA 10 confirmed at $130 after months of back-and-forth. No fireworks today, just a steady market filling in blanks that needed filling."},
    {date:"June 25, 2026", body:"<b>1991 Desert Shield #790</b> PSA 9 pushed higher to <span class='up'>$1,900</span> — up from $1,750. The Desert Shield premium keeps expanding. Quiet otherwise in '91."},
    {date:"June 24, 2026", body:"Quiet day for 1991. <b>1991 Fleer #450</b> PSA 9 dropped from $30 to <span class='down'>$20</span> and PSA 10 dipped from $84 to <span class='down'>$80</span>. Everything else confirmed existing prices — Desert Shield holding, Score inserts steady."},
    {date:"June 23, 2026", body:"<b>1991 Desert Shield All-Star #392</b> PSA 8 continues climbing — now at <span class='up'>$600</span>, up from $575 two days ago. Quiet strength across 1991 Score inserts: <b>1991 All-Star</b> PSA 9 up to <span class='up'>$30</span>, <b>1991 Dream Team</b> to <span class='up'>$25</span>, <b>1991 Rifleman</b> to <span class='up'>$17</span>. <b>1991 Topps #790</b> PSA 9 jumped from $18 to <span class='up'>$25</span>. The junk wax base is finding a floor and bouncing."},
    {date:"June 22, 2026", body:"<b>1991 Desert Shield All-Star #392</b> PSA 8 ticked up from $575 to <span class='up'>$590</span>. Desert Shield cards continue to hold strong — military-only distribution means supply isn't getting any bigger."},
    {date:"June 21, 2026", body:"<b>1991 Studio #112</b> PSA 10 climbed from $349 to <span class='up'>$374</span> at auction with 26 bids — the inaugural Studio set keeps building a cult following. <b>1991 Donruss #77</b> PSA 8 jumped from $7 to <span class='up'>$11</span>, and <b>1991 O-Pee-Chee Premier #56</b> PSA 9 moved from $12 to <span class='up'>$19</span>, finally correcting an old inversion where PSA 8 was priced higher than PSA 9."}
  ],
  1992: [
    {date:"September 26, 2026", body:"The <b>1992 Donruss Elite Series #13</b> remains the anchor of the year: a PSA 9 took 29 bids to <span class='down'>$1,003</span>, the PSA 8 sold at <span class='down'>$580</span> after 28 bids, and raw copies firmed from $450 to <span class='up'>$498</span>. <b>1992 Stadium Club Members Choice #603</b> PSA 10 came down hard, from $1,008 to <span class='down'>$660</span> across two contested auctions. <b>1992 Score All-Star #436</b> PSA 10 moved the other way, from $225 to <span class='up'>$275</span> on 24 bids."},
    {date:"September 20, 2026", body:"The <b>1992 Ultra Award Winners #22</b> PSA 10 climbed from $379 to <span class='up'>$504</span> (up 33%) after 36 bids, now within reach of the $570 the Ultra All-Star #6 brought in the same grade. <b>1992 Stadium Club Members Choice #603</b> PSA 10 eased from $1,215 to <span class='down'>$1,008</span> across three sales, including a 39-bid auction at $933, and its PSA 9 followed from $229 to <span class='down'>$172</span>. <b>1992 Fleer Pro-Visions #709</b> split: PSA 10 came down from $903 to <span class='down'>$810</span> on two auctions while PSA 9 rose from $92 to <span class='up'>$113</span>."},
    {date:"September 13, 2026", body:"<b>1992 Fleer Pro-Visions #709</b> PSA 10 sold twice on the same day, $985 after 42 bids and $821 after 19, and moved from $500 to <span class='up'>$903</span> (up 81%); a PSA 9 of the same card brings $92. The <b>1992 Donruss Elite Series #13</b>, numbered to 10,000, sold in PSA 9 for <span class='up'>$1,077</span>, up from $890 (up 21%). <b>1992 Stadium Club Members Choice #603</b> stayed the most active card of the year, with a PSA 10 at $1,200 and three PSA 9s that took that grade from $166 to <span class='up'>$229</span>."},
    {date:"September 9, 2026", body:"The <b>1992 Stadium Club Members Choice #603</b> PSA 10 climbed from $881 to <span class='up'>$1,229</span> (up 39%) in a 44-bid auction, with a second copy at $1,125 the same week. <b>1992 Fleer #279</b> PSA 10 jumped from $100 to <span class='up'>$170</span> (up 70%), and <b>1992 Ultra All-Star #6</b> PSA 9 from $47 to <span class='up'>$77</span> (up 64%). A PSA 10 of the <b>Pinnacle Idols #283</b> sold for <span class='up'>$87</span>."},
    {date:"September 6, 2026", body:"A PSA 10 of the <b>1992 Ultra All-Stars #6</b> sold for <span class='up'>$750</span>, up from $513 (up 46%) &mdash; the highest 1992 has produced outside the Donruss Elite Series. <b>Stadium Club Members Choice #603</b> was the year's most active card by a wide margin: eight PSA 9s between $166 and $251 lifted the grade from $209 to <span class='up'>$229</span>, while raw copies traded fourteen times in a $34-$53 band. <b>Triple Play Gallery of Stars #GS-8</b> PSA 10 jumped from $324 to <span class='up'>$525</span> (up 62%) in a 43-bid auction."},
    {date:"August 27, 2026", body:"<b>1992 Donruss Elite Series #13</b> PSA 10 sold for <span class='up'>$9,000</span>, up from $5,226. <b>1992 Stadium Club Members Choice #603</b> PSA 9 climbed from $84 to <span class='up'>$209</span> across a 5-sale cluster. <b>1992 O-Pee-Chee Premier Base #167</b> PSA 10 more than doubled, from $62 to <span class='up'>$148</span>."},
    {date:"August 21, 2026", body:"<b>1992 Studio Base #232</b> PSA 10 jumped from $515 to <span class='up'>$850</span> (up 65%) on a clean fixed-price sale. <b>1992 Stadium Club Members Choice #603</b> PSA 9 more than doubled, from $46 to <span class='up'>$112</span> (up 143%), across an unusually active 11-sale day. <b>1992 Upper Deck Bloodlines #85</b> PSA 10 sold for $87."},
    {date:"August 9, 2026", body:"<b>1992 Studio Base #232</b> raw tumbled from $45 to <span class='down'>$8</span> (down 82%). <b>1992 Fleer Team Leaders #15</b> PSA 9 jumped from $100 to <span class='up'>$175</span> (up 75%), and <b>1992 Topps Base #50</b> PSA 10 slipped from $65 to <span class='down'>$51</span>."},
    {date:"July 31, 2026", body:"<b>1992 Fleer Pro-Visions #709</b> PSA 10 jumped from $320 to <span class='up'>$500</span> (up 56%), the biggest percentage move in the set this week. <b>1992 Stadium Club Members Choice #603</b> PSA 10 climbed further to <span class='up'>$607</span>, putting it among the priciest 1992 Griffeys outside Team Leaders #15. <b>1992 Skydome #70</b> gets its first tracked PSA 10 ($143) and raw ($13) prices, closing one of the last gaps in the 1992 Stadium Club lineup."},
    {date:"July 25, 2026", body:"<b>1992 Donruss Triple Play Gallery of Stars #GS-8</b> PSA 10 sold for $324, up from $203, on a 30-bid auction. <b>1992 Donruss #24</b> PSA 10 jumped from $45 to <span class='up'>$60</span>, and <b>1992 Fleer #279</b> PSA 10 from $91 to <span class='up'>$99</span>. Cooling: <b>1992 Stadium Club Members Choice #603</b> PSA 8 fell from $25 to <span class='down'>$14</span>."},
    {date:"July 15, 2026", body:"The <b>1992 Stadium Club Members Choice #603</b> PSA 10 climbed from $375 to <span class='up'>$462</span> (up 23%) in a 31-bid auction, and the <b>1992 Studio #232</b> PSA 10 from $455 to <span class='up'>$550</span> (up 21%) — its raw copies moved from $13 to <span class='up'>$45</span> too. <b>1992 Topps Gold #50</b> rose at both grades: PSA 10 from $220 to <span class='up'>$261</span> with 33 bids and PSA 9 from $27 to <span class='up'>$37</span>. <b>1992 Score All-Star #436</b> PSA 10 jumped from $140 to <span class='up'>$200</span> (up 43%), <b>1992 Fleer #279</b> PSA 10 from $62 to <span class='up'>$100</span> (up 61%), <b>1992 Ultra #123</b> PSA 10 from $70 to <span class='up'>$89</span>, <b>1992 Bowman #100</b> PSA 10 from $93 to <span class='up'>$110</span>, and <b>1992 Donruss #165</b> PSA 10 from $60 to <span class='up'>$70</span>. The <b>1992 Elite Series #13</b> raw rose from $355 to <span class='up'>$417</span>. <b>1992 Fleer Team Leaders #15</b> traded heavily — eight PSA 8 copies sold between $27 and $40, and raw copies went from $3 to <span class='up'>$38</span>. An <b>1992 Ultra Award Winners #22</b> PSA 9 sold for $35. Pulling back: <b>1992 Upper Deck #424</b> PSA 10 from $199 to <span class='down'>$89</span> (down 55%) in a 21-bid auction, <b>1992 Studio #232</b> PSA 9 from $77 to <span class='down'>$56</span>, and <b>1992 Bowman #100</b> PSA 9 from $40 to <span class='down'>$26</span>."},
    {date:"July 10, 2026", body:"<b>1992 Donruss Elite #13</b> keeps climbing — a PSA 9 sold for $999.99 two days after the PSA 10's $5,226 auction, moving the grade from $822 to <span class='up'>$1,000</span>. Junk wax raw showed life underneath: first raw prices on <b>1992 Pinnacle #549</b> at $24 and <b>1992 Topps #50</b> at $19, and <b>1992 Studio #232</b> raw up from $7 to <span class='up'>$13</span>. <b>1992 Donruss #165</b> PSA 10 rose from $45 to <span class='up'>$60</span> and <b>1992 Bloodlines #85</b> PSA 8 from $12 to <span class='up'>$19</span>. <b>1992 Stadium Club Members Choice #603</b> PSA 9 gave back its recent gain, falling from $67 to <span class='down'>$36</span> at auction, and <b>1992 Topps #50</b> PSA 9 slipped from $18 to <span class='down'>$15</span> on two sales."},
    {date:"July 9, 2026", body:"The <b>1992 Donruss Elite #13</b> showed its whole ladder in one week: a PSA 10 sold for <span class='up'>$5,226</span> at auction with 45 bids, a PSA 9 brought $822, and even a PSA 7 cleared $516. One of 10,000 printed in an era when serial numbers barely existed, and gem copies almost never surface. <b>1992 Studio #232</b> rose across three grades — PSA 10 from $410 to <span class='up'>$455</span> at auction, PSA 9 from $49 to <span class='up'>$77</span>, PSA 8 from $25 to <span class='up'>$40</span>. <b>1992 Upper Deck Diamond Skills #650</b> PSA 10 climbed from $45 to <span class='up'>$60</span>. On the other side, <b>1992 Stadium Club Members Choice #603</b> PSA 10 slipped from $399 to <span class='down'>$375</span> and <b>1992 Ultra #123</b> PSA 10 gave back from $77 to <span class='down'>$70</span>."},
    {date:"June 29, 2026", body:"The <b>1992 Donruss Elite #13</b> had been priced at $875 raw and $550 PSA 8 — numbers that clearly didn't reflect where the market actually was. Multiple sales today in the $350-$450 range brought both figures back to earth. It's still a significant card, one of only 10,000 printed in an era when numbered cards barely existed, but the old prices were stale. Meanwhile the <b>1992 Studio #232</b> PSA 10 pushed to <span class='up'>$410</span> with 26 bidders competing — that hourglass portrait design from '92 photographs better than anything else in the year and collectors know it."},
    {date:"June 24, 2026", body:"Sales came in across the board but nothing moved — Topps Gold PSA 10, Upper Deck PSA 10, Leaf PSA 10, and Score All-Star PSA 10 all confirmed at existing prices. Stable market in '92."},
    {date:"June 23, 2026", body:"Split market in '92 today. <b>1992 Upper Deck #424</b> PSA 10 nearly doubled from $105 to <span class='up'>$199</span>. <b>1992 Leaf #392</b> PSA 10 surged from $99 to <span class='up'>$150</span> — those tough black borders make gems scarce. <b>1992 Bowman #100</b> PSA 9 jumped from $22 to <span class='up'>$40</span>. But inserts cooled: <b>1992 Score All-Star</b> PSA 10 dropped hard from $270 to <span class='down'>$140</span> at auction with 19 bids, and <b>1992 Studio #232</b> PSA 9 fell from $60 to <span class='down'>$49</span>. Gem mint base climbing while mid-grade inserts give back."},
    {date:"June 22, 2026", body:"<b>1992 Ultra #123</b> PSA 10 moved from $70 to <span class='up'>$77</span> at auction with 15 bids, while PSA 9 softened from $27 to <span class='down'>$23</span>. The gap between 9 and 10 is widening on early Ultra — gem copies are getting scarcer."},
    {date:"June 21, 2026", body:"<b>1992 Ultra Award Winners #22</b> PSA 10 jumped from $226 to <span class='up'>$300</span> — a 33% move at auction with 19 bids. Filled in <b>1992 Stadium Club Members Choice #603</b> PSA 9 at $50 from five separate auctions ($39-$66). <b>1992 Fleer #279</b> PSA 9 dropped from $25 to <span class='down'>$17</span>. The Donruss Elite /10,000 in PSA 7 hit $404 at auction — that card commands respect in any grade."}
  ],
  1993: [
    {date:"September 26, 2026", body:"The <b>1993 Finest Refractor #110</b> sold raw for <span class='down'>$8,256</span> after 53 bids, down from $8,899 &mdash; still the most expensive Griffey card of the decade outside the E-X Credentials family. The base <b>Finest #110</b> traded eight times raw between $103 and $154, settling from $145 to <span class='down'>$129</span>, and its PSA 10 eased from $2,350 to <span class='down'>$2,150</span> across two auctions of 37 and 43 bids. <b>1993 Upper Deck Fifth Anniversary #A1</b> was the busiest card of the year with twelve raw sales from $30 to $77, and a pair of PSA 8s sold at $575 and $560."},
    {date:"September 20, 2026", body:"A PSA 10 of the <b>1993 Donruss Elite Dominators #12</b>, numbered to 5,000, sold for <span class='up'>$1,837</span> after 31 bids, more than four times the $432 its PSA 9 brought in August. The <b>1993 Finest #110</b> climbed at the top two grades, PSA 10 from $1,827 to <span class='up'>$2,350</span> (up 29%) and PSA 9 from $352 to <span class='up'>$433</span> on three sales, while five raw sales eased it from $160 to <span class='down'>$145</span>. The <b>1993 Upper Deck Fifth Anniversary #A1</b> was the most-traded 1993 card again with 19 raw sales, settling from $64 to <span class='down'>$40</span>."},
    {date:"September 13, 2026", body:"<b>1993 Finest #110</b> softened in every grade this week: six raw copies took it from $196 to <span class='down'>$160</span>, three PSA 9s from $420 to <span class='down'>$352</span>, and a 27-bid PSA 8 auction from $225 to <span class='down'>$203</span>. <b>1993 Topps Black Gold #33</b> PSA 10 eased from $800 to <span class='down'>$699</span>. The base-card gems held firm, with <b>1993 Bowman #375</b> PSA 10 up from $155 to <span class='up'>$164</span> on 21 bids and <b>1993 Score #504</b> PSA 10 from $130 to <span class='up'>$148</span>."},
    {date:"September 9, 2026", body:"A <b>1993 Finest Refractor #110</b> drew 53 bids and sold ungraded for <span class='up'>$8,899</span> &mdash; a graded copy of the same card carries $13,600 in PSA 9 and $42,000 in PSA 10. <b>1993 Topps Murphy #56</b> rose from $218 to <span class='up'>$245</span> in PSA 10. The <b>1993 Donruss Elite Dominator #12</b> (/5,000) eased in both grades, PSA 8 from $215 to <span class='down'>$181</span> on a 21-bid auction and ungraded copies from $135 to <span class='down'>$113</span>."},
    {date:"September 6, 2026", body:"A PSA 10 of the <b>1993 Topps Black Gold #33</b> sold for <span class='up'>$800</span>, up from $599 &mdash; roughly seventeen times what the same card brings in PSA 9. <b>1993 Select Stars #19</b> traded across all three grades in a week, its PSA 9 climbing from $125 to <span class='up'>$146</span> and the PSA 8 more than doubling from $28 to <span class='up'>$65</span>. The <b>1993 Pinnacle Home Run Club #13</b> PSA 9 nearly doubled as well, $55 to <span class='up'>$95</span> on two sales."},
    {date:"August 27, 2026", body:"<b>1993 Finest Base #110</b> raw climbed from $114 to <span class='up'>$174</span> across a wide sales cluster this week. <b>1993 Stadium Club #707</b> PSA 9 jumped from $25 to <span class='up'>$355</span> on an 11-bid auction. <b>1993 Diamond Kings #DK-1</b> PSA 9 rose from $94 to <span class='up'>$135</span>."},
    {date:"August 21, 2026", body:"<b>1993 Finest Base #110</b> PSA 8 more than doubled from $108 to <span class='up'>$225</span> (up 108%), while its raw and PSA 9 tiers also firmed to $114 and $342 across a busy week. <b>1993 Donruss Elite Dominator #12</b> PSA 9 climbed from $351 to <span class='up'>$480</span> (up 37%). <b>1993 Donruss Base #553</b> PSA 10 rose from $135 to <span class='up'>$163</span> on a 7-bid auction."},
    {date:"August 9, 2026", body:"<b>1993 Upper Deck Homerun Heroes #HR9</b> sold in PSA 10 for $560 on a 31-bid auction. <b>1993 Finest Base #110</b> PSA 9 climbed from $255 to <span class='up'>$290</span>, while raw copies moved from $80 to <span class='up'>$100</span>. <b>1993 Flair Base #270</b> PSA 10 pulled back from $250 to <span class='down'>$220</span>."},
    {date:"July 25, 2026", body:"<b>1993 Topps Gold #179</b> PSA 10 sold for $350, up from $310. <b>1993 Leaf #319</b> PSA 10 climbed from $99 to <span class='up'>$112</span>, and <b>1993 Ultra Award Winners #16</b> PSA 9 from $35 to <span class='up'>$40</span>. <b>1993 Finest Base #110</b> PSA 8 eased from $113 to <span class='down'>$108</span> on a 25-bid auction."},
    {date:"July 19, 2026", body:"A <b>1993 Topps Black Gold #33</b> sold for <span class='up'>$599</span> in PSA 10, and the <b>1993 Stadium Club Members Only #59</b> PSA 10 jumped from $401 to <span class='up'>$589</span> (up 47%). The <b>1993 Donruss Diamond Kings #DK-1</b> PSA 10 eased from $1,500 to <span class='down'>$1,176</span> in a 24-bid auction."},
    {date:"July 15, 2026", body:"Finest kept running. The <b>1993 Finest #110</b> PSA 10 rose from $1,500 to <span class='up'>$1,925</span> (up 28%), and the PSA 9 from $240 to <span class='up'>$348</span> (up 45%) on four sales in two days between $244 and $400. <b>1993 SP Platinum Power #PP9</b> PSA 9 climbed from $158 to <span class='up'>$260</span> (up 65%), <b>1993 Select Stars #19</b> PSA 9 from $85 to <span class='up'>$125</span> (up 47%), and <b>1993 Ultra #619</b> PSA 10 from $69 to <span class='up'>$115</span> (up 67%) in a 24-bid auction. <b>1993 Score Dream Team #536</b> PSA 10 moved from $70 to <span class='up'>$80</span>, and an <b>1993 SP #4</b> PSA 8 sold for $24. <b>1993 Upper Deck #355</b> PSA 10 sold at $70, right on its mark."},
    {date:"July 10, 2026", body:"<b>1993 Finest #110</b> traded heavily — five sales across grades in four days. First PSA 8 data landed at <span class='up'>$113</span> in a 19-bid auction, the PSA 9 confirmed at $240 twice, and three raw sales between $82 and $94 held raw copies at $90. <b>1993 Diamond Kings #DK-1</b> raw nearly tripled from $10 to <span class='up'>$29</span>. <b>1993 Leaf #319</b> cooled at the top: PSA 10 from $125 to <span class='down'>$99</span> and PSA 9 from $28 to <span class='down'>$25</span>."},
    {date:"July 9, 2026", body:"First PSA 10 price on the <b>1993 Donruss Diamond Kings #DK-1</b>: <span class='up'>$1,500</span> — a low-pop gem on a card everybody owned raw. <b>1993 Stadium Club Members Choice #591</b> PSA 10 also got its first number, $148 on a pop-17 card. The <b>1993 Finest #110</b> keeps building: PSA 9 from $221 to <span class='up'>$240</span> on two same-day sales and raw copies from $66 up to <span class='up'>$90</span>. <b>1993 Topps #179</b> PSA 10 rose from $65 to <span class='up'>$90</span>, and <b>1993 Diamond Kings</b> PSA 8 ticked up from $27 to <span class='up'>$36</span>. <b>1993 SP Platinum Power #PP9</b> PSA 9 pulled back from $200 to <span class='down'>$158</span> at auction, and <b>1993 Black Gold #33</b> PSA 9 gave back its June jump, falling from $60 to <span class='down'>$35</span>."},
    {date:"June 29, 2026", body:"Big blank-fill day across 1993 and a few real moves underneath. The <b>1993 SP Platinum Power #PP9</b> PSA 9 had been sitting at a question mark forever — it's a die-cut holographic insert from a year before die-cuts were common, and the first graded data finally landed at <span class='up'>$200</span>. The <b>1993 Finest Base #110</b> raw pulled back from $90 to <span class='down'>$66</span>, a correction that makes more sense given the PSA 9 is $221 — raw copies shouldn't be trading at a 75% discount to the graded version. <b>1993 Black Gold #33</b> PSA 9 jumped from $35 to <span class='up'>$60</span> on a clean fixed-price sale. Plenty of new data points landed today that didn't exist yesterday — Leaf, Select Stars, Pinnacle inserts all getting their first PSA grades in the data."},
    {date:"June 24, 2026", body:"Sales activity but no price changes after yesterday's Finest Refractor fireworks. Upper Deck #355 PSA 10 confirmed at $70. Prices holding."},
    {date:"June 23, 2026", body:"The one we've been waiting for. <b>1993 Finest Refractor #110</b> PSA 9 sold for <span class='up'>$13,600</span> at auction with 47 bids — the original Finest Refractor Griffey, and now the second most expensive card in the entire guide. Only the 1998 Crusade Red sits higher. This is THE card that launched the refractor era. <b>1993 Upper Deck #355</b> PSA 10 bounced back from $61 to <span class='up'>$70</span>."},
    {date:"June 22, 2026", body:"<b>1993 Select #2</b> PSA 10 climbed from $61 to <span class='up'>$75</span>. <b>1993 Ultra #619</b> PSA 10 dipped from $75 to <span class='down'>$69</span> at auction. Mixed signals in '93 — some gems gaining, others giving back."},
    {date:"June 21, 2026", body:"Cooling off across the board. <b>1993 Upper Deck #355</b> PSA 10 dropped from $70 to <span class='down'>$61</span>, <b>1993 Pinnacle Home Run Club</b> PSA 9 fell from $55 to <span class='down'>$45</span>, and <b>1993 SP Platinum Power</b> PSA 8 slid from $34 to <span class='down'>$25</span>. Added <b>1993 Donruss Diamond Kings</b> PSA 8 at $27 and <b>1993 Topps Gold #179</b> PSA 9 at $27 — solid mid-tier fills."}
  ],
  1994: [
    {date:"September 25, 2026", body:"<b>1994 Flair Hot Gloves #3</b> was the year's busiest high-end card with six raw sales between $295 and $499, easing from $450 to <span class='down'>$411</span>, while a PSA 10 sold for <span class='up'>$2,200</span>. A raw <b>1994 Finest Refractor #232</b> sold for <span class='up'>$1,650</span>, up from $1,250 (up 32%). <b>1994 SP Holoview Blue FX #12</b> PSA 9 climbed from $130 to <span class='up'>$225</span> (up 73%). Lower down, <b>Ultra Home Run Kings #2</b> came back to earth across seven raw sales, from $42 to <span class='down'>$29</span>."},
    {date:"September 20, 2026", body:"A PSA 10 of the <b>1994 Upper Deck Next Generation Electric Diamond #6</b> sold for <span class='up'>$1,010</span> after 27 bids, more than four times the $234 its PSA 8 brought in August. <b>1994 Bowman's Best Red Refractor #40</b> PSA 9 climbed from $600 to <span class='up'>$850</span> (up 42%), while the non-refractor Red #40 PSA 9 slipped from $100 to <span class='down'>$60</span>. A 27-bid auction took the <b>1994 Topps #400</b> PSA 10 from $400 to <span class='down'>$243</span>, back in line with the $300 its Gold parallel sold for in July."},
    {date:"September 13, 2026", body:"The <b>1994 Finest Refractor #232</b> PSA 8 sold for <span class='up'>$2,400</span>, up from $1,900 (up 26%), with a PSA 9 of the same card still at $3,400. <b>1994 SP #105</b> PSA 10 drew 26 bids and climbed from $185 to <span class='up'>$306</span> (up 65%). <b>1994 Flair Hot Gloves #3</b> went two ways: a raw copy brought <span class='up'>$489</span> after 25 bids, up from $375, while a PSA 10 eased from $2,266 to <span class='down'>$2,125</span>."},
    {date:"September 9, 2026", body:"A PSA 10 of the <b>1994 Upper Deck #224</b> drew 50 bids and closed at <span class='up'>$1,143</span>, up from $750 (up 52%) &mdash; the card also sold for $1,200 on a fixed-price listing the same day. <b>1994 Flair Hot Gloves #3</b> firmed at both ends, its PSA 9 from $840 to <span class='up'>$900</span> and ungraded copies from $350 to <span class='up'>$375</span> in a 22-bid auction. <b>1994 Stadium Club Finest #5</b> split hard: the PSA 9 doubled from $68 to <span class='up'>$135</span> while raw copies fell from $74 to <span class='down'>$35</span>."},
    {date:"September 6, 2026", body:"The <b>1994 Flair Hot Gloves #3</b> moved at every level this week &mdash; four PSA 10s between $2,200 and $2,350 lifted the grade from $2,000 to <span class='up'>$2,266</span>, and the PSA 9 nearly doubled from $425 to <span class='up'>$840</span>. A <b>1994 SP Holoview Red #12</b> PSA 9 sold for <span class='up'>$1,300</span>, more than triple the PSA 8 on a card that turns up once per 75 packs. The <b>Ultra Home Run Kings #2</b> PSA 9 climbed from $659 to <span class='up'>$1,000</span> (up 52%), a 1:36 insert whose raw copies still trade in the $40s."},
    {date:"August 27, 2026", body:"<b>1994 Flair Base #103</b> PSA 10 sold for <span class='up'>$521</span>, up from $300. <b>1994 Flair Hot Gloves #3</b> PSA 10 climbed from $1,825 to <span class='up'>$2,000</span>. <b>1994 Finest Refractor #232</b> PSA 8 jumped from $1,400 to <span class='up'>$1,900</span> (up 36%)."},
    {date:"August 21, 2026", body:"<b>1994 Topps Gold #400</b> PSA 9 more than doubled from $23 to <span class='up'>$55</span> (up 139%). <b>1994 Finest Refractor #232</b> PSA 9 climbed further to <span class='up'>$3,400</span>, extending its run as the priciest 1994 Griffey in the guide by a wide margin. <b>1994 Flair Hot Gloves #3</b> raw corrected back down from $400 to <span class='down'>$325</span> on a five-sale cluster that better reflects where the ungraded market actually sits."},
    {date:"August 9, 2026", body:"<b>1994 Flair Hot Gloves #3</b> PSA 10 jumped from $1,000 to <span class='up'>$1,825</span> (up 83%) on a 35-bid auction, with its PSA 9 and PSA 8 tiers also climbing to <span class='up'>$425</span> and <span class='up'>$345</span>. <b>1994 Donruss Elite #45</b> PSA 9 rose from $125 to <span class='up'>$205</span> (up 64%), and <b>1994 Select Crown Contenders</b> PSA 9 climbed from $65 to <span class='up'>$91</span> (up 40%)."},
    {date:"July 31, 2026", body:"<b>1994 Finest #232</b> raw more than doubled from $35 to <span class='up'>$85</span> (up 143%) &mdash; a sharp jump for a card that's normally cheap to find ungraded. <b>1994 Flair Hot Gloves #3</b> PSA 10 climbed further to <span class='up'>$1,523</span>, extending its run as the priciest 1994 Griffey in the guide by a wide margin. <b>1994 Outfield Power #6</b> gets its first tracked price, a $190 PSA 10."},
    {date:"July 19, 2026", body:"The <b>1994 Flair Hot Gloves #3</b> PSA 10 climbed from $1,200 to <span class='up'>$1,300</span> at auction. An <b>1994 Ultra Award Winners #6</b> sold for $325 in PSA 10 with 47 bids, and the <b>1994 Studio #101</b> PSA 10 rose from $240 to <span class='up'>$280</span>."},
    {date:"July 15, 2026", body:"A <b>1994 Finest Refractor #232</b> PSA 8 sold for <span class='up'>$1,400</span>, slotting between raw copies at $866 and the PSA 9 at $3,040. The <b>1994 Finest base #232</b> PSA 10 rose from $550 to <span class='up'>$601</span>, and an <b>1994 SP Holoview Red #12</b> PSA 8 sold for $400. <b>1994 Flair Hot Gloves #3</b> raw climbed from $198 to <span class='up'>$250</span> (up 26%). A <b>1994 Studio #101</b> PSA 10 sold for $240, a <b>1994 Topps #400</b> PSA 10 for $153 in a 19-bid auction, and a <b>1994 Donruss Elite #45</b> PSA 8 for $60. <b>1994 Dugout Dirt #7</b> PSA 10 moved from $105 to <span class='up'>$113</span>, and <b>1994 Leaf Gold Stars #4</b> split — PSA 9 up from $190 to <span class='up'>$230</span>, raw down from $72 to <span class='down'>$44</span>. <b>1994 Leaf Power Brokers #5</b> PSA 10 eased from $158 to <span class='down'>$130</span> in a 23-bid auction."},
    {date:"July 10, 2026", body:"<b>1994 Stadium Club Finest #5</b> raw more than doubled from $13 to <span class='up'>$31</span>, led by a 22-bid auction at $36.55. <b>1994 Pinnacle The Naturals #3</b> raw moved from $17 to <span class='up'>$25</span> on three same-day sales, and <b>1994 Leaf Power Brokers #5</b> PSA 9 climbed from $25 to <span class='up'>$29</span> at auction. <b>1994 SP #105</b> was mixed — the PSA 10 confirmed at $200, first PSA 8 data arrived at $22, and the PSA 9 eased from $40 to <span class='down'>$35</span> on a second same-day sale. <b>1994 Dugout Dirt #7</b> PSA 10 slipped from $125 to <span class='down'>$105</span>. First raw prices: <b>1994 SP Holoview FX #12</b> at $21 and <b>1994 Mickey Mantle's Long Shots #MM10</b> at $20."},
    {date:"July 9, 2026", body:"Steady day in '94 — sale after sale confirmed existing prices: <b>1994 Flair Hot Gloves</b> PSA 10 at exactly $1,200, <b>1994 Finest #232</b> PSA 10 at $550, <b>1994 Leaf Statistical Standouts</b> PSA 10 at $480, <b>1994 Stadium Club Finest #5</b> PSA 9 at $84 with 21 bids, plus a stack of raw confirmations. <b>1994 SP #105</b> PSA 10 bounced back from $158 to <span class='up'>$200</span> after its late-June dip. <b>1994 Select Crown Contenders</b> raw gave back its spike, falling from $78 to <span class='down'>$38</span> at auction with 14 bids. First PSA 8 data on the <b>1994 Leaf Limited Gold All-Stars /10,000</b> landed at $40."},
    {date:"July 8, 2026", body:"<b>1994 Flair Hot Gloves #3</b> PSA 10 jumped from $750 to <span class='up'>$1,200</span> — the third grade on this die-cut to move up in three weeks. <b>1994 Finest Base #232</b> PSA 10 climbed from $450 to <span class='up'>$550</span>, with five raw sales in four days confirming $31. <b>1994 Stadium Club Finest #5</b> PSA 9 rose from $52 to <span class='up'>$84</span> at auction with 21 bids, and <b>1994 Select Crown Contenders</b> raw moved from $16 to <span class='up'>$78</span>. <b>1994 Leaf Statistical Standouts</b> PSA 10 dipped from $550 to <span class='down'>$480</span>."},
    {date:"June 27, 2026", body:"<b>1994 Finest Base #232</b> raw nearly doubled from $17 to <span class='up'>$30</span> — demand is spreading beyond the refractor. <b>1994 Dugout Dirt #7</b> PSA 10 climbed from $95 to <span class='up'>$125</span>. Added <b>1994 Dugout Dirt Members Only</b> with PSA 8 at $31 and PSA 9 at $65. Filled in blanks on <b>1994 Pinnacle Museum Collection</b> raw $32, <b>1994 Select Crown Contenders</b> raw $16, <b>1994 Leaf Slideshow</b> raw $8, and <b>1994 Topps Black Gold</b> PSA 8 at $18."},
    {date:"June 24, 2026", body:"<b>1994 Flair Hot Gloves #3</b> PSA 8 climbed from $300 to <span class='up'>$335</span> — this die-cut keeps getting more expensive. <b>1994 Flair Base #103</b> PSA 9 also jumped from $31 to <span class='up'>$40</span>. The Flair brand is quietly one of the strongest in '94."},
    {date:"June 23, 2026", body:"<b>1994 SP #105</b> PSA 10 dropped from $200 to <span class='down'>$158</span> at auction with 33 bids — strong data pulling it down. <b>1994 Leaf Power Brokers</b> PSA 10 also softened from $173 to <span class='down'>$158</span>. Premium base cards in '94 are cooling while the chase inserts (Finest Refractor, Flair Hot Gloves) hold firm."},
    {date:"June 22, 2026", body:"Added <b>1994 Flair Hot Gloves #3</b> PSA 8 at $300 with a die-cut tag — first PSA 8 data on one of the most beautiful die-cut inserts of the decade. The PSA 9 sits at $325 so the 8-to-9 gap is tight on this one."},
    {date:"June 21, 2026", body:"<b>1994 Finest Refractor #232</b> PSA 9 surged from $2,300 to <span class='up'>$3,040</span> at auction with 31 bids. That's a 32% jump on one of the most iconic refractors of the decade. The technology was brand new in '94 and these cards are brutally hard to find in high grade."}
  ],
  1995: [
    {date:"September 25, 2026", body:"The <b>1995 Pinnacle #128</b> bubble gum card was the busiest Griffey card the guide has ever tracked in one week &mdash; forty-four raw sales between $38 and $85, settling from $63 to <span class='down'>$54</span>. Its graded tiers held up far better: PSA 9 traded five times between $500 and $650, and the <b>Museum Collection</b> parallel took 72 bids to <span class='up'>$1,107</span> in PSA 9. <b>1995 Leaf Limited Gold #6</b> PSA 10 sold for <span class='up'>$1,500</span>, up from $420, one of the largest single moves of the week. <b>1995 Pinnacle White Hot #WH2</b> PSA 9 climbed from $1,300 to <span class='up'>$1,726</span> on a 34-bid auction."},
    {date:"September 20, 2026", body:"The <b>1995 Pinnacle Bubble Gum #128</b> moved in both directions: PSA 9 climbed from $508 to <span class='up'>$572</span> on three sales, including a 27-bid auction at $600, and PSA 8 from $175 to <span class='up'>$228</span>, while 26 raw sales eased it from $92 to <span class='down'>$63</span>. A PSA 9 of the <b>1995 Pinnacle Red Hot #RH2</b> sold for <span class='up'>$400</span>, about a tenth of the $3,878 its PSA 10 brought earlier this month. <b>1995 Ultra Power Plus #2</b> PSA 9 climbed from $150 to <span class='up'>$250</span> (up 67%), well clear of the $83 its PSA 8 sold for two weeks ago."},
    {date:"September 13, 2026", body:"The <b>1995 Pinnacle #128</b> bubble gum card traded every day this week: five PSA 9s between $495 and $550 held it at <span class='up'>$508</span>, seven PSA 8s brought it from $192 to <span class='down'>$175</span>, and twelve raw copies moved it from $61 to <span class='up'>$92</span>. Its <b>Museum Collection #128</b> parallel climbed from $417 to <span class='up'>$538</span> (up 29%), the top sale an 18-bid auction at $670. <b>1995 Pinnacle Team Pinnacle #TP7</b>, the Griffey/Bonds dufex, sold ungraded for <span class='up'>$330</span> after 30 bids, up from $125 (up 164%)."},
    {date:"September 9, 2026", body:"The <b>1995 Pinnacle #128</b> bubble gum card was the most heavily traded Griffey of the week by a wide margin, with forty-five ungraded sales between $32 and $100 settling it at <span class='down'>$61</span>, down from $64, while its PSA 8 rose from $175 to <span class='up'>$192</span> across six sales. <b>1995 Ultra Hitting Machines Gold Medallion #6</b> doubled off a 24-bid auction, from $66 to <span class='up'>$133</span> (up 102%). <b>1995 Flair Hot Numbers #4</b> split, its PSA 9 climbing from $260 to <span class='up'>$340</span> (up 31%) while ungraded copies eased from $77 to <span class='down'>$55</span> on six sales."},
    {date:"September 6, 2026", body:"A PSA 9 of the <b>1995 Pinnacle Artist's Proof #128</b> sold for <span class='up'>$1,925</span> in a 53-bid auction, up from $841 (up 129%) &mdash; a 1:24 insert now worth nearly four times the base Bubble Gum card in the same grade. The <b>Red Hot #RH2</b> went further still, a PSA 10 taking <span class='up'>$3,878</span> across 50 bids. Underneath both, the base <b>#128</b> traded constantly: two dozen raw copies between $56 and $89, and nine PSA 9s clustered at <span class='up'>$507</span>."},
    {date:"August 27, 2026", body:"<b>1995 Flair Hot Glove #3</b> debuted in PSA 10 at $2,000 on a 52-bid auction. <b>1995 Pinnacle Museum Collection Swing Men #304</b> raw climbed from $92 to <span class='up'>$305</span> across the week (up 232%). <b>1995 Studio Platinum #5</b> PSA 10 rose from $377 to <span class='up'>$625</span> (up 66%)."},
    {date:"August 20, 2026", body:"The <b>1995 Pinnacle Base #128</b> PSA 10 climbed from $3,000 to <span class='up'>$5,225</span> (up 74%) on a 55-bid auction &mdash; the priciest base card in the guide. The <b>1995 Select Certified Gold Team #1</b> debuted in PSA 10 at $2,725. <b>1995 Bowman's Best Red Refractors #49</b> raw climbed from $270 to <span class='up'>$470</span> (up 74%)."},
    {date:"August 16, 2026", body:"<b>1995 Topps Opening Day #3</b> PSA 10 nearly tripled, climbing from $65 to <span class='up'>$178</span> (up 174%) on a 3-bid auction. <b>1995 Select Certified Gold Team #1</b> raw more than doubled, from $190 to <span class='up'>$400</span> (up 111%). <b>1995 Pinnacle Museum Collection #128</b> &mdash; the priciest Bubble Gum parallel in the guide &mdash; climbed too, raw from $385 to <span class='up'>$550</span> (up 43%), with PSA 8 following from $525 to <span class='up'>$625</span>."},
    {date:"August 9, 2026", body:"<b>1995 Select Certified Mirror Gold #70</b> PSA 9 climbed from $525 to <span class='up'>$564</span> on a 23-bid auction, with a PSA 8 selling for $430. <b>1995 Pinnacle Base #128</b> (Bubble Gum) PSA 9 jumped from $310 to <span class='up'>$360</span> (up 16%) on a 27-bid auction, while <b>1995 Studio Gold #5</b> PSA 10 rose from $190 to <span class='up'>$250</span> (up 32%)."},
    {date:"August 3, 2026", body:"<b>1995 Leaf Limited Gold #6</b> PSA 9 more than doubled from $71 to <span class='up'>$160</span> (up 125%). The <b>1995 Pinnacle Museum Collection #128</b> parallel set a new high in PSA 9, up from $925 to <span class='up'>$975</span> &mdash; its third straight climb. The base <b>1995 Bubble Gum #128</b> PSA 9 also firmed, from $258 to <span class='up'>$310</span>."},
    {date:"July 29, 2026", body:"A PSA 10 <b>1995 Pinnacle Bubble Gum #128</b> sold for <span class='up'>$3,000</span>, up from $2,800. The PSA 9 tier cooled on a wave of sales, moving from $365 to <span class='down'>$258</span>. <b>1995 Topps #397</b> PSA 10 climbed from $140 to <span class='up'>$180</span>."},
    {date:"July 25, 2026", body:"The <b>1995 Pinnacle #128 Bubble Gum</b> keeps climbing &mdash; PSA 9 up from $309 to <span class='up'>$365</span> and PSA 8 confirmed at <span class='up'>$130</span> across three separate sales (up from $127). <b>1995 Museum Collection #128</b> PSA 9 hit a new high at <span class='up'>$925</span>, up from $878. <b>1995 Studio Platinum #5</b> PSA 10 jumped from $225 to <span class='up'>$290</span>, and <b>1995 Studio Gold #5</b> PSA 9 from $50 to <span class='up'>$65</span>. <b>1995 Leaf Limited Gold #6</b> PSA 9 firmed from $66 to <span class='up'>$71</span>, and <b>1995 Leaf Statistical Standouts /5,000</b> raw rebounded from $180 to <span class='up'>$299</span>. Cooling: <b>1995 Finest #118</b> PSA 9 from $103 to <span class='down'>$83</span> on an 11-bid auction, and <b>1995 Ultra Power Plus Gold Medallion #2</b> raw from $96 to <span class='down'>$70</span>. The base raw Bubble Gum market stayed extremely active with a dozen-plus sales in the $45-$80 band &mdash; a $305 auction outlier didn't move the needle given how consistent the rest of the cluster was."},
    {date:"July 19, 2026", body:"The <b>1995 Pinnacle #128 Bubble Gum</b> stayed the most active card in the set. The PSA 10 edged from $2,745 to <span class='up'>$2,800</span>, the PSA 9 from $298 to <span class='up'>$309</span> in a 19-bid auction, and raw copies climbed from $55 to <span class='up'>$80</span> (up 45%) on contested auctions at $80 and $81. A <b>1995 Pinnacle White Hot #WH2</b> sold for $1,225 in PSA 9. Select Certified moved at the top: <b>1995 Gold Team #1</b> PSA 9 from $415 to <span class='up'>$515</span> (up 24%) and <b>1995 Mirror Gold #70</b> PSA 9 from $504 to <span class='up'>$525</span> in a 29-bid auction. A <b>1995 Bowman's Best Red Refractor #49</b> raw sold for $270 after 31 bids. Pulling back: <b>1995 Leaf Statistical Standouts /5,000</b> raw from $236 to <span class='down'>$180</span> and <b>1995 Swing Men Museum Collection #304</b> raw from $110 to <span class='down'>$100</span>."},
    {date:"July 15, 2026", body:"A 46-bid auction moved the <b>1995 Pinnacle #128 Bubble Gum</b> PSA 10 from $2,223 to <span class='up'>$2,745</span> (up 23%) — the strongest sale yet on the most recognizable Griffey of the decade. The PSA 9 followed from $285 to <span class='up'>$298</span> across a stack of sales, raw copies moved from $45 to <span class='up'>$55</span>, and a <b>1995 Museum Collection #128</b> PSA 8 jumped from $349 to <span class='up'>$500</span> (up 43%). <b>1995 Leaf Statistical Standouts /5,000</b> PSA 9 rose from $280 to <span class='up'>$419</span> (up 50%) on back-to-back auctions, and a raw copy sold for $236. <b>1995 Donruss Elite #54</b> split — PSA 9 up from $168 to <span class='up'>$208</span>, raw down from $750 to <span class='down'>$98</span> in a 15-bid auction. Leaf Limited moved across the board: <b>1995 Lumberjacks #4</b> PSA 9 from $110 to <span class='up'>$165</span> (up 50%), <b>1995 Bat Patrol</b> PSA 10 from $165 to <span class='up'>$202</span>, and <b>1995 Gold #6</b> PSA 9 from $105 to <span class='down'>$66</span>. A <b>1995 Finest #118</b> PSA 9 sold for $103, <b>1995 Leaf #211</b> PSA 10 edged from $92 to <span class='up'>$95</span>, and <b>1995 Swing Men Museum Collection</b> raw rose from $58 to <span class='up'>$110</span>."},
    {date:"July 12, 2026", body:"The <b>1995 Pinnacle #128 Bubble Gum</b> traded heavily again and the grades split. PSA 9 rose from $265 to <span class='up'>$285</span> on two sales at $275 and $295, while PSA 8 eased from $155 to <span class='down'>$125</span> and raw settled from $65 to <span class='down'>$45</span> across a stack of sales between $40 and $66. The <b>1995 Swing Men #304</b> saw graded sales at $50 in PSA 9 and $165 in PSA 10. <b>1995 Flair Hot Numbers</b> raw fell from $60 to <span class='down'>$39</span>, matched by a 14-bid auction and a fixed-price sale at the same level. An <b>1995 Emotion N-Tense #6</b> raw sold for $25, and <b>1995 Select Big Sticks</b> raw held at $56."},
    {date:"July 8, 2026", body:"Eleven <b>1995 Pinnacle Bubble Gum</b> sales in four days moved every grade: raw from $50 to <span class='up'>$65</span>, PSA 8 from $109 to <span class='up'>$155</span> at auction, and PSA 9 to <span class='up'>$265</span> across four sales. The <b>1995 Museum Collection</b> parallel filled in raw at $375. <b>1995 Finest Base #118</b> got its first PSA 10 sale at <span class='up'>$850</span> (POP 17), and <b>1995 Flair Base #81</b> PSA 10 rose to <span class='up'>$310</span> while its PSA 9 doubled to <span class='up'>$65</span>. <b>1995 Flair Hot Numbers</b> PSA 9 fell from $200 to <span class='down'>$149</span>, and <b>1995 Topps #397</b> PSA 10 dropped from $196 to <span class='down'>$140</span> on back-to-back sales."},
    {date:"June 29, 2026", body:"The 1995 Flair insert set just got repriced. <b>1995 Hot Numbers</b> PSA 10 hit <span class='up'>$1,801</span> with 44 bids — the first gem mint sale ever recorded on this card. Hot Numbers was already commanding $200 in PSA 9, but $1,801 for a 10 puts it in a different conversation. These Flair die-cuts from '95 are brutally hard to center and gem copies are genuinely rare. The <b>1995 Hot Glove</b> PSA 8 jumped from $42 to <span class='up'>$113</span> at auction, and Outfield Power got its first PSA 10 data at $275. Meanwhile the Bubble Gum raw keeps grinding higher — $50 now with no sign of stopping. That card moves more units than anything else in 1995."},
    {date:"June 27, 2026", body:"The Bubble Gum card is the most liquid card in the hobby right now — 15+ raw sales in two days, all landing in the $40-$50 range. Raw ticked up from $41 to <span class='up'>$46</span>. <b>1995 Select Big Sticks</b> raw up from $52 to <span class='up'>$58</span>. <b>1995 Leaf Limited Gold #6</b> PSA 9 jumped from $85 to <span class='up'>$105</span>. Filled in <b>1995 Flair Hot Glove</b> raw at $42 and <b>1995 Studio Platinum</b> raw at $50."},
    {date:"June 24, 2026", body:"<b>1995 Emotion #77</b> PSA 10 moved from $189 to <span class='up'>$203</span> at auction with 38 bids. Added <b>1995 Leaf Limited Gold #6</b> PSA 10 at $420 — first data on that card. Everything else confirmed — Bubble Gum holding steady at $114 PSA 8 and $250 PSA 9."},
    {date:"June 23, 2026", body:"<b>1995 Pinnacle Bubble Gum #128</b> gave back yesterday's gains — PSA 9 settled from $258 back to <span class='down'>$240</span> with multiple sales in the $230-$250 range, and PSA 8 dipped from $118 to <span class='down'>$114</span>. The iconic card is finding its level. <b>1995 Flair Outfield Power</b> PSA 9 held at $61, confirming yesterday's move."},
    {date:"June 22, 2026", body:"<b>1995 Flair Outfield Power #7</b> PSA 9 moved from $50 to <span class='up'>$61</span> at auction with 13 bids. Flair inserts from '95 are quietly gaining — the Hot Glove, Hot Numbers, and Outfield Power set is underrated."},
    {date:"June 21, 2026", body:"<b>1995 Pinnacle Bubble Gum #128</b> PSA 9 ticked up from $240 to <span class='up'>$258</span> with multiple sales in the $245-$270 range. Added PSA 8 at $118 — that's the entry point for the most iconic Griffey image ever put on cardboard. On the flip side, <b>1995 Topps #397</b> PSA 9 dropped hard from $24 to <span class='down'>$15</span>."}
  ],
  1996: [
    {date:"September 25, 2026", body:"<b>1996 Ultra Thunderclap #11</b> nearly doubled, $1,300 to <span class='up'>$2,550</span> raw (up 96%) after a 30-bid auction &mdash; the strongest '96 insert result of the week. Metal Universe pulled in two directions: the <b>1996 Metal Universe #107</b> base card was the busiest Griffey card of the week with twenty raw sales between $50 and $120, easing from $79 to <span class='down'>$75</span>, while its <b>Platinum Edition</b> parallel climbed from $225 to <span class='up'>$242</span> across seven sales. The set's <b>Heavy Metal #4</b> went the other way entirely, down from $52 to <span class='down'>$26</span> (down 50%) across thirteen sales that never once cleared $37."},
    {date:"September 20, 2026", body:"A PSA 10 of the <b>1996 Finest Mystery Finest Refractor #M16</b> sold for <span class='up'>$4,163</span> after 34 bids, more than sixteen times the $254 its last PSA 8 brought. The <b>1996 Bowman's Best Refractor #71</b> PSA 9 climbed from $559 to <span class='up'>$875</span> (up 57%) in a week when the base #71 PSA 9 drew 21 bids and sold for $67, up from $30. <b>1996 Metal Universe #107</b> was the busiest 1996 card again with 24 raw sales, firming from $73 to <span class='up'>$79</span>, while its Platinum Edition PSA 8 moved from $700 to <span class='up'>$755</span>."},
    {date:"September 13, 2026", body:"<b>1996 Flair Hot Gloves #4</b> PSA 8 sold for <span class='up'>$900</span>, up from $222 (up 305%), the same week its 1997 counterpart set the guide's Hot Gloves high-water mark; a PSA 10 of this one is still $5,555. The <b>1996 SP Special FX Holoview Die-Cut #10</b> PSA 10 drew 36 bids and went from $500 to <span class='up'>$1,175</span> (up 135%). <b>1996 Metal Universe Base #107</b> was the busiest card of the week, 19 raw sales between $60 and $99, and held from $72 to <span class='up'>$73</span>."},
    {date:"September 8, 2026", body:"The <b>1996 Ultra Prime Leather Gold Medallion #6</b> drew 64 bids and closed at <span class='up'>$202</span>, up from $103 (up 96%). <b>1996 Metal Universe #107</b> moved the other way on heavy volume, twenty-six ungraded sales between $56 and $114 pulling it from $98 to <span class='down'>$72</span>. <b>1996 Flair Diamond Cuts #5</b> raw climbed from $184 to <span class='up'>$341</span> (up 85%), with its PSA 10 holding at $4,000."},
    {date:"September 6, 2026", body:"The <b>1996 Finest Gold Intimidators Refractor #135</b> PSA 9 climbed from $2,002 to <span class='up'>$3,000</span> (up 50%) &mdash; roughly ten times what a PSA 9 of the base #135 brings. <b>1996 Pinnacle Skylines #1</b>, a 1:29 pull, nearly doubled in PSA 8 from $1,400 to <span class='up'>$2,695</span>, closing hard on its $5,400 PSA 9. <b>1996 Metal Universe #107</b> traded 33 raw copies this week and clustered at <span class='down'>$105</span> &mdash; supply that keeps the base card well under the Platinum Edition's $285."},
    {date:"August 27, 2026", body:"<b>1996 Metal Universe Mother Lode #3</b> raw climbed from $87 to <span class='up'>$194</span> this week (up 123%). A <b>1996 Pinnacle Skylines #1</b> PSA 9 sold for <span class='up'>$5,400</span>, up from $5,000. <b>1996 Ultra Thunderclap #11</b> PSA 8 jumped from $3,000 to <span class='up'>$3,750</span>."},
    {date:"August 20, 2026", body:"The <b>1996 Leaf Limited Lumberjacks Black (/500)</b> debuted in PSA 10 at $3,750 on a 29-bid auction &mdash; the priciest Lumberjacks tier in the guide. The <b>1996 Bowman's Best Preview Atomic Refractor #BBP30</b> PSA 10 pulled back from $3,850 to <span class='down'>$2,800</span> (down 27%) on a 35-bid auction. <b>1996 Metal Universe Platinum Edition #107</b> PSA 8 climbed from $480 to <span class='up'>$700</span>, with raw copies also up sharply across a cluster of sales."},
    {date:"August 11, 2026", body:"<b>1996 Topps Chrome Star Power Refractor #90</b> PSA 9 jumped from $2,000 to <span class='up'>$2,356</span> on a 25-bid auction. <b>1996 Metal Universe Base #107</b> climbed across the board &mdash; PSA 9 from $480 to <span class='up'>$585</span>, PSA 8 from $200 to <span class='up'>$250</span>, raw from $90 to <span class='up'>$103</span>. <b>1996 Starburst Artist's Proof #41</b> raw more than doubled, from $99 to <span class='up'>$250</span>."},
    {date:"August 9, 2026", body:"<b>1996 Metal Universe Base #107</b> raw settled at $90, down from $148, after more than a dozen sales this week clustered tightly in the $70-90 range. <b>1996 Fleer Update Base #U223</b> &mdash; the non-Tiffany parallel, previously untracked &mdash; joined the guide at $125 PSA 10. <b>1996 E-Motion XL D-Fense #4</b> got its first raw and PSA 8 prices, $104 and $90, after a run of sales under the insert's alternate name, 'Legion of Boom,' filled in the card's real market."},
    {date:"August 6, 2026", body:"<b>1996 Finest Refractor #135</b> PSA 9 nearly doubled from $975 to <span class='up'>$1,926</span> (up 97%) on a 29-bid auction. <b>1996 Finest Gold Intimidators #135</b> raw climbed from $220 to <span class='up'>$350</span> (up 59%). <b>1996 Metal Universe Platinum Edition #107</b> raw eased from $434 to <span class='down'>$300</span>."},
    {date:"August 3, 2026", body:"A <b>1996 Pinnacle Skylines #1</b> PSA 9 sold for <span class='up'>$5,000</span>, well above the card's PSA 8 mark of $1,400. The <b>1996 Bowman's Best Preview Atomic Refractor #BBP30</b> PSA 10 jumped from $2,124 to <span class='up'>$3,850</span> (up 81%). <b>1996 Fleer Metal Universe Platinum Edition #107</b> PSA 9 climbed from $900 to <span class='up'>$1,500</span> (up 67%)."},
    {date:"July 29, 2026", body:"A PSA 10 <b>1996 Flair Base #160</b> sold for <span class='up'>$2,500</span>. The <b>1996 Stadium Club Extreme Winners Silver #EW8</b> PSA 10 climbed from $281 to <span class='up'>$830</span> (up 195%), and a <b>1996 Bowman Base #79</b> PSA 10 jumped from $75 to <span class='up'>$205</span> (up 173%)."},
    {date:"July 22, 2026", body:"Fleer Ultra's Gold Medallion parallels led &mdash; the <b>1996 Thunder Clap Gold Medallion #11</b> brought <span class='up'>$4,425</span> in a 36-bid auction (PSA 7) and the <b>1996 Hitting Machines Gold Medallion #4</b> a first PSA 9 at <span class='up'>$3,833</span>. The <b>1996 Metal Universe Platinum #107</b> PSA 8 jumped from $150 to <span class='up'>$600</span> and a raw <b>1996 Pinnacle Skylines #1</b> sold for <span class='up'>$1,700</span>, up from $1,200. The base <b>1996 Thunder Clap #11</b> raw firmed from $1,200 to <span class='up'>$1,250</span>, while the <b>1996 Bowman's Best Preview Refractor #BBP30</b> raw fell from $196 to <span class='down'>$101</span>."},
    {date:"July 17, 2026", body:"Refractors led the day. The <b>1996 Bowman's Best Preview Atomic Refractor #BBP30</b> PSA 10 jumped from $1,450 to <span class='up'>$2,124</span> (up 46%) on two same-day sales at $2,124 and $2,100, and the <b>1996 Preview Refractor #BBP30</b> raw went from $95 to <span class='up'>$196</span> (up 106%) in a 31-bid auction. The <b>1996 Topps Chrome Star Power Refractor #90</b> PSA 9 rose from $1,580 to <span class='up'>$2,000</span> (up 27%), and the <b>1996 Finest Refractor #305</b> PSA 9 from $550 to <span class='up'>$950</span> (up 73%). <b>1996 Ultra Hitting Machines #4</b> raw climbed from $425 to <span class='up'>$559</span> on two sales, a <b>1996 Metal Universe #107</b> PSA 9 sold for $399, and the <b>1996 Metal Universe Platinum #107</b> raw moved from $140 to <span class='up'>$188</span> in a 28-bid auction. Mid-tier inserts kept pace: <b>1996 Collector's Choice #310 Gold Signature</b> raw from $50 to <span class='up'>$144</span> (up 188%) with 24 bids, <b>1996 Fleer Zone #3</b> raw from $75 to <span class='up'>$100</span>, <b>1996 Mystery Finest Refractor #M25</b> raw from $50 to <span class='up'>$85</span>, <b>1996 Finest Sterling #24</b> PSA 9 from $42 to <span class='up'>$70</span>, <b>1996 Studio Stained Glass Stars #2</b> raw from $164 to <span class='up'>$190</span> on two sales, <b>1996 Ultra Gold Medallion #126</b> PSA 8 from $335 to <span class='up'>$350</span>, and <b>1996 Leaf Hats Off #5</b> raw from $60 to <span class='up'>$70</span>. A <b>1996 Call to the Hall #2</b> PSA 10 sold for $300, a day after another brought $250. Cooling: <b>1996 Ultra Thunder Clap #11</b> raw from $1,725 to <span class='down'>$1,200</span> (down 30%), <b>1996 Score Titanic Taters #4</b> PSA 10 from $609 to <span class='down'>$550</span> in a 42-bid auction, <b>1996 Ultra Gold Medallion #126</b> raw from $120 to <span class='down'>$91</span>, and <b>1996 Pinnacle Starburst #41</b> raw from $82 to <span class='down'>$75</span> on three sales. <b>1996 Topps Sweet Strokes</b> raw ticked up from $130 to <span class='up'>$135</span>."},
    {date:"July 14, 2026", body:"A raw <b>1996 Pinnacle Skylines #1</b> sold for <span class='up'>$1,200</span>. The <b>1996 Bowman's Best Preview Refractor #BBP30</b> PSA 9 climbed from $225 to <span class='up'>$450</span> (up 100%) at auction, while the <b>1996 Preview Atomic Refractor #BBP30</b> eased from $645 to <span class='down'>$475</span> (down 26%). <b>1996 Stadium Club Extreme Winners Gold #EW8</b> raw climbed from $676 to <span class='up'>$850</span> (up 26%). Metal Universe was mixed — <b>1996 Platinum Edition #107</b> raw rebounded from $70 to <span class='up'>$140</span> (up 100%), <b>1996 Base #107</b> raw from $33 to <span class='up'>$48</span>, and <b>1996 Heavy Metal #4</b> from $47 to <span class='up'>$52</span>, but <b>1996 Base #107</b> PSA 8 slipped from $150 to <span class='down'>$125</span> and <b>1996 Mother Lode #3</b> PSA 8 from $64 to <span class='down'>$46</span>. <b>1996 Select En Fuego #1</b> raw moved from $265 to <span class='up'>$290</span> and <b>1996 Leaf Hats Off #5</b> raw from $50 to <span class='up'>$60</span>. On the downside, <b>1996 Topps Sweet Strokes</b> raw gave back its recent gain from $160 to <span class='down'>$130</span>, <b>1996 Ultra Diamond Producers Gold Medallion #3</b> raw from $100 to <span class='down'>$80</span>, and <b>1996 Extreme Winners Silver #EW8</b> raw from $55 to <span class='down'>$43</span>."},
    {date:"July 12, 2026", body:"The <b>1996 Ultra Thunder Clap #11</b> led the day — the PSA 8 climbed from $2,500 to <span class='up'>$3,000</span> and a raw copy hit <span class='up'>$1,725</span> at auction with 36 bids, up from $900. <b>1996 Donruss Power Alley #10</b> traded across three grades — PSA 9 up from $199 to <span class='up'>$245</span>, PSA 8 from $295 to <span class='down'>$118</span> in a 17-bid auction, and raw from $234 to <span class='down'>$100</span>. <b>1996 Ultra Power Plus #3</b> PSA 9 moved from $130 to <span class='up'>$165</span>, <b>1996 Topps Sweet Strokes</b> raw from $135 to <span class='up'>$160</span>, and the <b>1996 Ultra 22 Karat Gold Leaf</b> raw from $55 to <span class='up'>$79</span>. An <b>1996 Ultra Respect Gold Medallion</b> sold at $75 in PSA 8 and a <b>1996 Leaf Preferred Steel #52</b> at $60 in PSA 9. On the downside, <b>1996 Finest Refractor #305</b> raw eased from $366 to <span class='down'>$255</span>, <b>1996 SPx Commemorative #KG1</b> PSA 10 fell from $404 to <span class='down'>$335</span>, and a group of Metal Universe raws softened — <b>1996 Platinum Edition</b> from $108 to <span class='down'>$70</span>, <b>1996 Heavy Metal</b> from $66 to <span class='down'>$47</span>, and <b>1996 Mother Lode</b> from $86 to <span class='down'>$75</span>."},
    {date:"July 10, 2026", body:"A 41-bid auction sent the <b>1996 Finest Refractor #135</b> PSA 8 from $560 to <span class='up'>$1,250</span> — more than PSA 9 copies have been bringing. First PSA 10 data on the <b>1996 You Make the Play Gold Signature #16</b> landed at $1,335, and the <b>1996 Stadium Club Extreme Winners Silver #EW8</b> PSA 9 debuted at $195. The raw insert market was broadly up: <b>1996 Finest Refractor #305</b> from $250 to <span class='up'>$366</span>, <b>1996 Ultra Diamond Producers Gold Medallion</b> doubled from $50 to <span class='up'>$100</span>, <b>1996 Metal Universe Platinum #107</b> from $81 to <span class='up'>$108</span>, <b>1996 Mystery Finest Refractor #M16</b> from $45 to <span class='up'>$73</span>, and the <b>1996 Leaf Limited Pennant Craze</b> and <b>1996 Lumberjacks</b> from $42 to <span class='up'>$72</span> and <span class='up'>$70</span>, with Mother Lode, Stained Glass, Select Certified Red and Fleer Zone all up behind them. Graded strength too: <b>1996 Sterling Refractor #24</b> PSA 9 from $536 to <span class='up'>$625</span>, <b>1996 Starburst Artist's Proof</b> PSA 9 from $220 to <span class='up'>$333</span>, and <b>1996 Metal Universe #107</b> PSA 8 from $90 to <span class='up'>$150</span>. Two gave back: <b>1996 Ultra Thunder Clap #11</b> raw from $1,000 to <span class='down'>$900</span> and <b>1996 Fleer Update Diamond Tribute #3</b> raw from $159 to <span class='down'>$104</span>."},
    {date:"July 8, 2026", body:"<b>1996 Metal Universe Platinum Edition</b> raw dropped hard — four sales in four days between $74 and $150 brought it from $330 to <span class='down'>$81</span>, and PSA 8 followed from $400 to <span class='down'>$150</span>. Elsewhere prices climbed: <b>1996 Flair Diamond Cuts #5</b> PSA 10 sold for <span class='up'>$2,127</span> at auction, <b>1996 Leaf Limited Lumberjacks #1</b> PSA 10 jumped from $325 to <span class='up'>$500</span>, and <b>1996 Finest Sterling Refractor #24</b> raw doubled from $200 to <span class='up'>$400</span> on back-to-back sales. <b>1996 Topps Chrome #70</b> PSA 9 hit <span class='up'>$100</span> for the first time."},
    {date:"July 4, 2026", body:"The rarest cards in 1996 don't trade often — but when they do, they rewrite the record book. The <b>1996 Select Certified Mirror Blue /45</b> finally showed its hand: a raw copy went to <span class='up'>$4,496</span> at auction with 41 bids, the first ungraded data point ever on a card where only 45 exist. Twenty minutes of bidding told us more about that card than two years of guessing. Same story with the <b>1996 Topps Chrome Refractor #70</b> — the original '96 Chrome refractor had never shown a PSA 9 price until one hammered at <span class='up'>$3,905</span> with 36 bids. And the <b>1996 Ultra Hitting Machines</b> die-cut, already one of the toughest pulls of the year at 1:288, landed its first PSA 9 at <span class='up'>$1,259</span>. Underneath the fireworks, the serial-numbered Donruss stuff keeps waking up: <b>1996 Power Alley /5,000</b> raw jumped from $95 to <span class='up'>$234</span> and the <b>1996 Summit Big Bang /600</b> more than tripled from $70 to <span class='up'>$232</span>. Not everything cooperated — <b>1996 Studio Stained Glass Stars</b> raw slid from $150 to <span class='down'>$114</span> on back-to-back sales. But the theme of the day was discovery: three cards that never had a market price before now have serious ones."},
    {date:"June 29, 2026", body:"<b>1996 Studio Press Proof Silver #116</b> wasn't even in this guide 24 hours ago. Then it sold for <span class='up'>$2,828</span> with 16 bids. That's what happens when a low-pop parallel from a forgotten set suddenly gets discovered — a card that doesn't even show up in most price searches just repriced the whole Studio category overnight. Meanwhile the refractor market stayed hot: <b>1996 Finest Refractor #305</b> PSA 8 pushed through $400 for the first time, and the <b>1996 Wrecking Crew Refractor</b> PSA 8 jumped $87 to <span class='up'>$350</span> — two Topps Chrome refractors from '96 that have been quietly gaining for months. The <b>1996 Metal Universe Platinum Edition</b> raw doubled from $150 to <span class='up'>$330</span>, which tells you something about what serious collectors think that card is worth ungraded. Not everything went up — <b>1996 Power Alley</b> PSA 9 dropped hard from $500 to <span class='down'>$199</span>, erasing months of gains in one sale. The 1996 market is full of these extremes right now: underappreciated cards exploding, overpriced cards resetting. The Studio Press Proof Silver is exactly why you watch the sold listings every day."},
    {date:"June 25, 2026", body:"<b>1996 Flair Hot Gloves</b> raw climbed from $200 to <span class='up'>$265</span>. <b>1996 Bowman's Best Cuts Atomic Refractor</b> raw surged from $400 to <span class='up'>$600</span> — a 50% jump on one of the most sought-after die-cuts in '96. <b>1996 Stadium Club Extreme Winners Gold</b> landed at raw $676 — first data on that card. Metal Universe cooled: <b>1996 Mother Lode</b> raw dipped to <span class='down'>$85</span> and <b>1996 Platinum Edition</b> raw eased to <span class='down'>$120</span>."},
    {date:"June 27, 2026", body:"<b>1996 Bowman's Best Cuts Atomic Refractor</b> PSA 8 more than doubled from $400 to <span class='up'>$925</span> at auction with 17 bids. <b>1996 Hitting Machines</b> raw surged from $200 to <span class='up'>$429</span> at auction with 37 bids — that die-cut is getting chased hard. <b>1996 Best Cuts Refractor</b> raw climbed from $125 to <span class='up'>$165</span>. <b>1996 Platinum Edition</b> raw up to <span class='up'>$150</span>. <b>1996 Summit Above and Beyond</b> filled in raw at $93 and PSA 9 jumped from $100 to <span class='up'>$130</span>. On the other side, <b>1996 Titanium</b> raw corrected from $44 to <span class='down'>$30</span> with multiple lower sales, and <b>1996 Ultra Call to the Hall</b> raw dropped from $13 to <span class='down'>$6</span>. The Bowman's Best die-cuts are the hottest cards in 1996 right now."},
    {date:"June 24, 2026", body:"<b>1996 Bowman's Best Cuts Atomic Refractor #1</b> PSA 9 more than doubled from $500 to <span class='up'>$1,150</span>. <b>1996 Leaf Limited Lumberjacks Black (/500)</b> landed at PSA 9 $700 — first graded data on that card. <b>1996 Call to the Hall Gold Medallion</b> PSA 8 jumped from $89 to <span class='up'>$140</span>. <b>1996 E-Motion XL D-Fense</b> filled in PSA 10 at $150. The 1996 insert market is running hot."},
    {date:"June 23, 2026", body:"<b>1996 Metal Universe Platinum Edition</b> PSA 8 more than doubled from $130 to <span class='up'>$300</span> — the parallel premium on this card is real. <b>1996 Finest Gold Intimidators</b> PSA 9 climbed from $355 to <span class='up'>$400</span>. <b>1996 Flair Diamond Cuts</b> PSA 9 surged from $210 to <span class='up'>$300</span>. The high-end 1996 inserts are on fire right now — anything with scarcity is being chased hard."},
    {date:"June 22, 2026", body:"<b>1996 Finest Sterling Refractor #24</b> climbing — PSA 9 moved from $490 to <span class='up'>$536</span> at auction with 38 bids, and PSA 8 jumped from $250 to <span class='up'>$370</span>. On the other side, <b>1996 Metal Universe Mother Lode</b> PSA 9 pulled back from $191 to <span class='down'>$165</span>, and <b>1996 Ultra Call to the Hall Gold Medallion</b> PSA 9 dropped from $337 to <span class='down'>$285</span>. <b>1996 Mystery Finest Refractor #M25</b> PSA 8 also cooled from $152 to <span class='down'>$100</span>."},
    {date:"June 21, 2026", body:"Big movers today. <b>1996 Summit Above & Beyond</b> PSA 10 nearly doubled from $460 to <span class='up'>$800</span>. <b>1996 Score Titanic Taters</b> PSA 10 jumped from $440 to <span class='up'>$609</span> at auction with 29 bids. <b>1996 Collector's Choice #370</b> PSA 10 surged from $46 to <span class='up'>$70</span>. <b>1996 Metal Universe Mother Lode</b> PSA 9 confirmed at $191. <b>1996 Flair Diamond Cuts</b> raw moved from $90 to <span class='up'>$115</span>."}
  ],
  1997: [
    {date:"September 25, 2026", body:"The <b>1997 Bowman's Best Best Cuts Atomic Refractor #BC6</b> went from $475 to <span class='up'>$1,225</span> raw (up 158%) across three sales, one of them a 32-bid auction that closed at $1,225 and another at $1,500 &mdash; the Atomic has pulled well clear of the standard Best Cuts refractor, which still trades at $320. <b>1997 Metal Universe Blast Furnace #6</b> PSA 9 climbed from $215 to <span class='up'>$615</span> (up 186%) on a 16-bid auction, and its PSA 10 sold for $1,227 after 38 bids. The <b>1997 Metal Universe #145</b> base card was the busiest Griffey card of the week with twenty-two raw sales between $23.50 and $45, ten of them contested auctions; the price eased from $41 to <span class='down'>$33</span>."},
    {date:"September 20, 2026", body:"A PSA 9 of the <b>1997 SPx Die-Cut Gold #45</b> sold for <span class='up'>$1,765</span>, up from $451 (up 291%), about 40% of what the PSA 10 brought in July. <b>1997 Bowman Chrome International Refractor #12</b> PSA 9 climbed from $1,600 to <span class='up'>$2,450</span> (up 53%), restoring a real premium over the raw copy that sold for $2,249 in August. The <b>1997 Finest Warriors Refractor #139</b> drew 31 and 25 bids in back-to-back raw auctions and moved from $305 to <span class='up'>$760</span> (up 149%), above the $470 its last PSA 8 sold for."},
    {date:"September 13, 2026", body:"A PSA 10 of the <b>1997 Flair Showcase Hot Gloves #4</b> sold for <span class='up'>$16,256</span> after 64 bids, more than six times the $2,557 a PSA 9 brought five days earlier; a PSA 8 sold the same day for $2,500, up from $1,802. The <b>1997 Finest Gold Refractor #342</b> PSA 9 moved from $1,800 to <span class='up'>$5,027</span> (up 179%) on two auctions at $5,400 and $4,653 that drew 44 and 16 bids. <b>1997 Metal Universe Blast Furnace #6</b> PSA 10 sold four times in four days between $1,234 and $1,500, three of them 31-to-41-bid auctions, and moved from $1,126 to <span class='up'>$1,409</span> (up 25%)."},
    {date:"September 8, 2026", body:"The <b>1997 E-X 2000 #40</b> was the year's most heavily traded card, with eighteen ungraded sales lifting it from $114 to <span class='up'>$128</span>, while its PSA 9 climbed from $625 to <span class='up'>$1,025</span> (up 64%) in a 38-bid auction. <b>1997 Metal Universe #145</b> went the other way, six sales between $40 and $43 pulling it from $151 to <span class='down'>$41</span>. A PSA 9 of the <b>1997 Flair Showcase Hot Gloves #4</b> sold for <span class='up'>$2,557</span>, up from $1,700 (up 50%), on 42 bids."},
    {date:"September 3, 2026", body:"New to the guide: <b>1997 Topps Chrome Season's Best Refractor #SB8</b>, which debuts at $1,299 in PSA 9 &mdash; a big step up from the non-Refractor version's $196. <b>1997 Stadium Club Patent Leather #PL4</b> PSA 10 jumped from $1,450 to <span class='up'>$2,800</span>, and <b>1997 Topps Gallery of Heroes #GH4</b> PSA 10 climbed from $2,500 to <span class='up'>$3,500</span>. <b>1997 Fleer Ultra Home Run Kings #4</b> PSA 10 also pushed higher, from $1,500 to <span class='up'>$2,400</span>."},
    {date:"September 2, 2026", body:"<b>1997 Skybox Metal Universe Base #145</b> raw more than doubled, from $65 to <span class='up'>$151</span>, and <b>1997 Topps Base #300</b> PSA 10 jumped from $110 to <span class='up'>$227</span>. <b>1997 Score Artist's Proof #193</b> PSA 9 gave back three-quarters of its value, from $720 to <span class='down'>$180</span>, and <b>1997 Finest Gold Embossed #342</b> PSA 8 pulled back too, from $350 to <span class='down'>$152</span>. <b>1997 Skybox E-X 2000 Base #40</b> raw settled at $114, and <b>1997 Donruss Limited Counterparts #1</b> PSA 10 climbed from $100 to <span class='up'>$170</span>."},
    {date:"August 25, 2026", body:"The <b>1997 Topps Chrome Refractor #101</b> PSA 9 climbed from $2,358 to <span class='up'>$3,800</span> (up 61%) on a 39-bid auction, its biggest sale yet. <b>1997 Bowman Chrome International Refractor #12</b> raw more than doubled, from $1,100 to <span class='up'>$2,249</span> (up 104%), on a 40-bid auction. The <b>1997 All-Star Refractor #AS13</b> PSA 9 jumped from $825 to <span class='up'>$1,450</span> (up 76%) on a 38-bid auction."},
    {date:"August 20, 2026", body:"The <b>1997 Flair Showcase Legacy Collection Row 1 #24 (/100)</b> climbed from $2,400 to <span class='up'>$4,000</span> (up 67%), the priciest raw card in the set. The <b>1997 Bowman's Best International Refractor #BBI2</b> raw price climbed from $198 to <span class='up'>$743</span> (up 275%) on a cluster of sales all trading well above its old level. <b>1997 Bowman Chrome Refractor #12</b> moved across every grade, with PSA 9 leading the way from $949 to <span class='up'>$1,325</span> in a 37-bid auction."},
    {date:"August 16, 2026", body:"<b>1997 Flair Showcase Hot Gloves #4</b> PSA 8 jumped from $1,200 to <span class='up'>$1,802</span> (up 50%) in a 48-bid auction, and <b>1997 Diamond Cuts #5</b> PSA 10 climbed from $1,400 to <span class='up'>$2,000</span> (up 43%) &mdash; the whole Flair Showcase line moved together today. <b>1997 Ultra Home Run Kings #4</b> more than doubled, raw rising from $206 to <span class='up'>$450</span> (up 118%)."},
    {date:"August 11, 2026", body:"<b>1997 Bowman's Best International Refractor #BBI2</b> PSA 9 climbed from $700 to <span class='up'>$1,825</span> (up 161%) on a 27-bid auction. <b>1997 Metal Universe Mother Lode</b> raw pulled back from $2,500 to <span class='down'>$2,250</span>, and <b>1997 Circa Rave Reviews #4</b> raw jumped from $175 to <span class='up'>$300</span>."},
    {date:"August 9, 2026", body:"<b>1997 Ultra RBI King #7</b> joined the guide at $3,900 PSA 10 &mdash; one of the pricier debuts of the year. <b>1997 Stadium Club Patent Leather #PL4</b> got its first PSA 10 sale at $1,450, while the rarer Members Only parallel holds its own separate tier. <b>1997 Ultra Starring Role #2</b> PSA 10 climbed from $1,900 to <span class='up'>$2,600</span> (up 37%), and <b>1997 Metal Universe Mother Lode</b> jumped from $1,400 to <span class='up'>$2,500</span> raw."},
    {date:"August 6, 2026", body:"<b>1997 Topps Gallery of Heroes #GH4</b> PSA 10 jumped from $1,375 to <span class='up'>$2,500</span> (up 82%) at auction. <b>1997 Finest Masters #238</b> PSA 10 climbed from $171 to <span class='up'>$248</span>, and <b>1997 Fleer Night and Day</b> PSA 9 rose from $400 to <span class='up'>$525</span>. <b>1997 Score Platinum Team Parallel</b> (/2,000) debuted at $750 in PSA 9."},
    {date:"August 3, 2026", body:"<b>1997 Topps Sweet Strokes #SS6</b> PSA 10 jumped from $1,050 to <span class='up'>$1,861</span> (up 77%) in an 18-bid auction. A raw <b>1997 Topps Chrome Refractor #101</b> climbed from $1,100 to <span class='up'>$1,900</span> (up 73%). <b>1997 Leaf Knot-Hole Gang #2</b> PSA 10 rose from $440 to <span class='up'>$641</span> (up 46%)."},
    {date:"July 29, 2026", body:"A PSA 9 <b>1997 Metal Universe Mother Lode #4</b> sold for <span class='up'>$3,875</span>, up from $1,667 (up 132%). <b>1997 Donruss Elite Series #7</b> raw more than doubled from $100 to <span class='up'>$190</span> (up 90%), and the <b>1997 Metal Universe Blast Furnace #6</b> PSA 10 moved from $630 to <span class='up'>$727</span> (up 15%)."},
    {date:"July 22, 2026", body:"The <b>1997 Ultra Platinum Medallion #P121</b> PSA 8 climbed from $1,600 to <span class='up'>$2,656</span> (up 66%) in a 45-bid auction. The <b>1997 Metal Universe Magnetic Field #4</b> PSA 8 jumped from $95 to <span class='up'>$170</span> and a raw <b>1997 Ultra Thunder Clap #8</b> firmed from $400 to <span class='up'>$435</span>. On the downside, the <b>1997 Ultra Baseball Rules! #2</b> raw fell from $325 to <span class='down'>$109</span> and the <b>1997 Patent Leather Members Only #PL4</b> from $355 to <span class='down'>$150</span>."},
    {date:"July 19, 2026", body:"The <b>1997 Score Showcase Series Artist's Proof #156</b> PSA 10 pushed from $1,500 to <span class='up'>$1,775</span>, and the <b>1997 Topps Hobby Masters #HM1</b> PSA 10 from $550 to <span class='up'>$715</span> (up 30%). The <b>1997 Flair Showcase Diamond Cuts #5</b> raw eased from $475 to <span class='down'>$395</span> in a 42-bid auction."},
    {date:"July 18, 2026", body:"Inserts led the day. <b>1997 Ultra Baseball Rules! #2</b> raw jumped from $120 to <span class='up'>$325</span> (up 171%) in a 28-bid auction, and <b>1997 Studio Hard Hats #3</b> PSA 9 from $149 to <span class='up'>$300</span> (up 101%). The <b>1997 Leaf Statistical Standouts #3</b> PSA 10 rose from $1,300 to <span class='up'>$1,648</span> (up 27%) with 38 bids, with raw copies moving from $399 to <span class='up'>$450</span>. <b>1997 Metal Universe Blast Furnace</b> PSA 10 climbed from $385 to <span class='up'>$630</span> (up 64%) on two same-day sales, <b>1997 Topps Gallery of Heroes #GH4</b> raw from $480 to <span class='up'>$750</span> (up 56%), and <b>1997 Flair Showcase Row 0 #24</b> raw from $425 to <span class='up'>$650</span> (up 53%). <b>1997 Topps Chrome All-Star Refractor #AS13</b> PSA 9 moved from $641 to <span class='up'>$825</span>, <b>1997 Donruss Update Power Alley</b> PSA 9 from $550 to <span class='up'>$722</span> in a 29-bid auction, <b>1997 E-X 2000 Credentials /299</b> raw from $1,050 to <span class='up'>$1,200</span>, and <b>1997 Hall or Nothing #2</b> raw from $183 to <span class='up'>$250</span>. An <b>1997 E-X 2000 base #40</b> PSA 9 sold for $321, a <b>1997 Bowman's Best International Refractor</b> PSA 8 for $350, a <b>1997 Mirror Image Atomic Refractor</b> PSA 8 for $300, a <b>1997 Metal Universe Platinum Portraits</b> raw for $152 with 32 bids, and <b>1997 Ultra Diamond Producers #3</b> raw copies for $180 and $130. The <b>1997 Bowman's Best Refractor Preview #BBP2</b> sold twice — a PSA 9 for $360 and a PSA 8 for $175 in a 10-bid auction. <b>1997 Topps Sweet Strokes #SS6</b> traded six raw copies between $115 and $335, holding at $160, and the <b>1997 Mother Lode</b> raw sold at exactly $1,400 again. Cooling: <b>1997 Ultra Thunder Clap #8</b> raw from $700 to <span class='down'>$400</span> (down 43%), <b>1997 Finest Refractor #238</b> PSA 9 from $533 to <span class='down'>$275</span> (down 48%), <b>1997 Bowman's Best Atomic Refractor Preview #BBP2</b> raw from $300 to <span class='down'>$163</span> at auction, <b>1997 International Refractor</b> raw from $411 to <span class='down'>$163</span>, and <b>1997 E-X 2000 base</b> PSA 8 from $175 to <span class='down'>$155</span>."},
    {date:"July 14, 2026", body:"The <b>1997 Bowman's Best Atomic Refractor Preview #BBP2</b> PSA 10 jumped from $1,100 to <span class='up'>$2,550</span> (up 132%) at auction with 42 bids. The <b>1997 E-X 2000 A Cut Above #2</b> PSA 8 climbed from $3,252 to <span class='up'>$4,600</span> (up 41%), and the <b>1997 Metal Universe Mother Lode</b> raw jumped from $925 to <span class='up'>$1,400</span> (up 51%). <b>1997 Fleer Diamond Tributes #4</b> raw rose from $436 to <span class='up'>$740</span> (up 70%) in a 43-bid auction, and <b>1997 Topps Gallery of Heroes #GH4</b> PSA 9 moved from $525 to <span class='up'>$721</span> (up 37%). Raw prices firmed across the year: <b>1997 Metal Universe Titanium</b> from $81 to <span class='up'>$124</span>, <b>1997 Ultra Baseball Rules! #2</b> from $80 to <span class='up'>$120</span>, <b>1997 Topps Sweet Strokes #SS6</b> from $125 to <span class='up'>$160</span>, <b>1997 Gallery Peter Max #PM5</b> from $59 to <span class='up'>$90</span>, <b>1997 E-X 2000 base #40</b> back from $65 to <span class='up'>$85</span>, and <b>1997 Bowman's Best International Atomic Refractor #BBI2</b> from $610 to <span class='up'>$650</span>. A raw <b>1997 Finest Gold Embossed #342</b> sold for $90. Pulling back: <b>1997 Ultra Thunder Clap #8</b> raw from $800 to <span class='down'>$700</span> and <b>1997 Fleer Night and Day</b> raw from $108 to <span class='down'>$89</span>."},
    {date:"July 12, 2026", body:"The <b>1997 E-X 2000 A Cut Above #2</b> raw jumped from $1,250 to <span class='up'>$1,800</span>, one of the toughest pulls in the year at 1:288. The <b>1997 Ultra Thunder Clap #8</b> moved at both ends — PSA 8 from $1,500 to <span class='up'>$1,700</span> and raw from $400 to <span class='up'>$800</span> — and the <b>1997 Flair Showcase Hot Gloves #4</b> PSA 9 climbed from $1,250 to <span class='up'>$1,700</span>. <b>1997 Fleer Bleacher Blasters #4</b> raw rose from $186 to <span class='up'>$217</span>, <b>1997 Ultra Fame Game #1</b> raw from $33 to <span class='up'>$49</span>, and <b>1997 Collector's Choice Big Shots Gold Signature</b> raw from $29 to <span class='up'>$40</span>. A <b>1997 Fleer Zone #7</b> raw sold for $236, a <b>1997 Totally Certified Platinum Blue #136</b> at $80 in PSA 8, and a <b>1997 Topps base #300</b> at $22 in PSA 9. <b>1997 E-X 2000 base #40</b> raw eased from $85 to <span class='down'>$65</span>."},
    {date:"July 10, 2026", body:"The <b>1997 Finest Gold Refractor #342</b> got its first PSA 8 price: <span class='up'>$1,050</span>. The rest of Finest moved with it — <b>1997 Refractor #139</b> PSA 9 from $725 to <span class='up'>$795</span>, base <b>1997 #139</b> PSA 10 from $202 to <span class='up'>$225</span>. A raw <b>1997 Metal Universe Magnetic Field</b> sold for <span class='up'>$400</span>, up from $79 — PSA 9 money for an ungraded copy. <b>1997 Fleer Bleacher Blasters</b> raw climbed from $155 to <span class='up'>$186</span> in a 21-bid auction, <b>1997 Stadium Club Firebrand #FB5</b> raw from $115 to <span class='up'>$160</span> with first PSA 8 data at $125, <b>1997 Studio Hard Hats</b> raw from $80 to <span class='up'>$123</span>, and <b>1997 Leaf Dress for Success</b> raw from $72 to <span class='up'>$90</span>. First prices also landed on <b>1997 Topps Hobby Masters #HM1</b> PSA 9 at $190 and the <b>1997 Leaf Fractal Matrix Z-Axis Die-Cut /100</b> raw at $176. The other direction: <b>1997 Ultra Baseball Rules! #2</b> raw from $136 to <span class='down'>$80</span>, <b>1997 Donruss Preferred X-Ponential Power</b> raw from $150 to <span class='down'>$99</span>, <b>1997 Studio Press Proof Gold #16</b> raw from $147 to <span class='down'>$93</span>, and <b>1997 SPx Cornerstones of the Game</b> raw from $198 to <span class='down'>$172</span>."},
    {date:"July 8, 2026", body:"<b>1997 Bowman Chrome Refractor #12</b> PSA 9 jumped from $536 to <span class='up'>$949</span>. <b>1997 Flair Showcase Diamond Cuts #5</b> climbed in two grades — PSA 8 to <span class='up'>$510</span> and PSA 9 from $525 to <span class='up'>$750</span>, both at auction. <b>1997 Bowman's Best International Atomic Refractor</b> PSA 8 rose to <span class='up'>$609</span> with 27 bids. On the downside, <b>1997 Flair Showcase Row 0</b> raw fell from $640 to <span class='down'>$425</span> and <b>1997 Goudey Greats</b> PSA 9 dropped from $495 to <span class='down'>$340</span>. <b>1997 Leaf Dress for Success /3,500</b> split: PSA 9 up to <span class='up'>$200</span>, PSA 10 down to <span class='down'>$675</span>."},
    {date:"July 4, 2026", body:"The <b>1997 Stadium Club Patent Leather Members Only</b> PSA 10 just did something violent — $875 to <span class='up'>$2,449</span> in one auction, 38 bids deep. The regular Patent Leather confirmed around $204 raw the very next day, which means the Members Only premium isn't drifting higher, it's detonating. Die-cut, low-pop, and now a four-figure card in gem. The <b>1997 Finest with Coating #139</b> also got its first PSA 10 on the books at <span class='up'>$202</span>, and <b>1997 Flair Showcase Row 0</b> raw pushed to <span class='up'>$640</span> — that card refuses to cool off. The correction of the day was brutal but overdue: <b>1997 Collector's Choice Crash the Game Instant Winner</b> had been sitting at $800 raw on stale data, and a real 10-bid auction just reset it to <span class='down'>$178</span>. That's not a crash, that's a price finally telling the truth. <b>1997 X-Ponential Power /3,000</b> quietly climbed from $110 to <span class='up'>$150</span> — the Donruss Preferred serial-numbered cards keep finding new buyers."},
    {date:"June 26, 2026", body:"Mixed signals today. <b>1997 Ultra Home Run Kings</b> PSA 10 climbed from $1,375 to <span class='up'>$1,500</span>. <b>1997 Finest Refractor #139</b> PSA 9 jumped from $600 to <span class='up'>$725</span>. <b>1997 Leaf Statistical Standouts</b> PSA 9 ticked up to <span class='up'>$690</span>. But corrections hit hard elsewhere: <b>1997 Donruss Press Proofs Gold</b> PSA 10 cratered from $898 to <span class='down'>$550</span>, <b>1997 Sweet Strokes</b> raw dropped from $355 to <span class='down'>$148</span>, and <b>1997 Magnetic Field</b> raw sank to <span class='down'>$40</span>. The 1997 market is repricing in both directions."},
    {date:"June 27, 2026", body:"Correction day for 1997 Ultra raws. <b>1997 Thunder Clap</b> raw dropped from $548 to <span class='down'>$365</span> at auction with 47 bids. <b>1997 Home Run Kings</b> raw fell from $385 to <span class='down'>$206</span> at auction with 34 bids. <b>1997 Sweet Strokes</b> raw continued sliding to <span class='down'>$125</span>. <b>1997 Peter Max</b> raw dropped from $100 to <span class='down'>$59</span> at auction. But blanks are filling fast — <b>1997 Knot-Hole Gang</b> raw landed at $266, <b>1997 Baseball Rules</b> raw at $136, <b>1997 Best Cuts Refractor BC6</b> raw at $175, and <b>1997 Magnetic Field</b> bounced from $40 back to <span class='up'>$47</span>. The raw market is repricing hard while graded holds steady."},
    {date:"June 25, 2026", body:"<b>1997 Flair Showcase Row 0</b> PSA 9 dropped from $810 to <span class='down'>$679</span>. <b>1997 Blast Furnace</b> PSA 10 gave back gains, falling from $585 to <span class='down'>$530</span>. <b>1997 Magnetic Field</b> raw collapsed from $153 to <span class='down'>$79</span>. On the flip side, <b>1997 Flair Showcase Diamond Cuts</b> raw climbed from $375 to <span class='up'>$475</span>. Correction day for Metal Universe, but Flair Showcase inserts are holding strong."},
    {date:"June 24, 2026", body:"Sales confirmed existing prices across the board. Yesterday's Blast Furnace and Power Plus moves still settling. Nothing notable today."},
    {date:"June 23, 2026", body:"<b>1997 Metal Universe Blast Furnace</b> PSA 10 jumped from $350 to <span class='up'>$585</span> — a 67% move at 1:48 Hobby odds. Metal Universe inserts across '97 are heating up fast. <b>1997 Ultra Power Plus</b> PSA 9 sold for $1,009 at auction (29 bids, POP 3) — a card we hadn't even been tracking. The depth of demand in '97 keeps surprising."},
    {date:"June 29, 2026", body:"The 1997 market is running on a different engine right now. <b>1997 Flair Showcase Row 0</b> raw jumped from $355 to <span class='up'>$599</span> — when ungraded copies of a card start approaching $600, the graded population is getting very thin and very competitive. The <b>1997 Metal Universe Magnetic Field</b> had two separate auctions hit $103 raw on the same day, 34 bids combined — the holographic refractor design on this card catches light differently than anything else in the set and collectors are waking up to it. PSA 9 confirmed at $400. The <b>1997 Upper Deck Star Attractions Gold</b> PSA 8 more than doubled from $166 to <span class='up'>$350</span>, which is the kind of move that happens when a card has been sitting under the radar for years and one auction triggers the discovery. The <b>1997 Atomic Refractor Preview #BBP2</b> raw doubled to $300. 1997 is producing more $300-plus raw cards than any other year in the guide right now."},
    {date:"June 22, 2026", body:"<b>1997 E-X 2000 Hall or Nothing</b> PSA 9 surged from $375 to <span class='up'>$605</span> at auction with 29 bids — a 61% jump. The die-cut design on this card is iconic and demand is clearly accelerating. <b>1997 SPx Cornerstones of the Game</b> (w/ Bonds) PSA 8 softened from $350 to <span class='down'>$300</span>."},
    {date:"June 21, 2026", body:"Two monster moves. <b>1997 Finest Refractor #139</b> raw exploded from $368 to <span class='up'>$2,750</span> at auction — a Silver Embossed Refractor variant that went for 7x the previous price with 17 bids. <b>1997 Metal Universe Mother Lode</b> PSA 8 more than doubled from $870 to <span class='up'>$1,943</span> at auction with 23 bids. The 1:288 odds on Mother Lode are starting to get priced in."}
  ],
  1998: [
    {date:"September 20, 2026", body:"The <b>1998 Topps Chrome Refractor #321</b> PSA 10 sold for <span class='up'>$12,100</span> after 43 bids, up from $6,223 (up 94%), and now brings more than three times the $3,500 a PSA 9 fetched two weeks ago. <b>1998 Metal Universe Hardball Galaxy #206</b> was the most-traded card in the guide this week with 28 raw sales, nine of them contested auctions between $58 and $86, and settled from $95 to <span class='down'>$71</span>. <b>1998 Metal Universe Diamond Heroes #1DH</b> PSA 9 climbed from $550 to <span class='up'>$950</span> (up 73%) while seven raw sales eased it from $152 to <span class='down'>$126</span>."},
    {date:"September 13, 2026", body:"<b>1998 Bowman Chrome</b> led the week: the <b>International Refractor #33</b> PSA 9 moved from $525 to <span class='up'>$750</span> (up 43%) and the plain <b>Refractor #33</b> PSA 8 from $216 to <span class='up'>$381</span> (up 76%) on a 31-bid auction, both still well under the $4,000 a PSA 10 International brings. <b>1998 Metal Universe Hardball Galaxy #206</b> was the most-traded card in the guide, 24 raw sales in six days between $75 and $130, and settled from $102 to <span class='down'>$95</span>. The <b>1998 Pinnacle Museum Collection Artist's Proof #PP90</b> sold ungraded for <span class='up'>$305</span> after 27 bids, up from $125 (up 144%), nearly three times the $110 the standard Museum Collection brings."},
    {date:"September 8, 2026", body:"A PSA 10 of the <b>1998 Flair Showcase Legacy Collection Row 1 #1</b>, one of 100 copies, sold for <span class='up'>$26,988</span> in an 82-bid auction. The <b>1998 Metal Universe Titanium #1</b> PSA 8 climbed from $480 to <span class='up'>$1,075</span> (up 124%) on 27 bids. <b>Hardball Galaxy #206</b> was the year's most heavily traded card by a wide margin, with more than three dozen ungraded sales between $50 and $152 leaving it close to where it started, at <span class='down'>$102</span>."},
    {date:"September 2, 2026", body:"<b>1998 Metal Universe Universal Language</b> PSA 10 jumped from $347 to <span class='up'>$600</span> (up 73%), and <b>1998 Topps Finest Refractor #100</b> PSA 9 climbed from $333 to <span class='up'>$584</span>. <b>1998 Topps Stars Gold Rainbow</b> (/99) raw pushed to a new high, $1,425 to <span class='up'>$2,024</span>, while <b>1998 Stadium Club Triumvirate Luminous #T16B</b> PSA 9 pulled back hard, from $1,330 to <span class='down'>$849</span>. <b>1998 Hardball Galaxy #206</b> stayed the most-traded card in the guide all week, settling at $103 raw and $395 in PSA 9 after dozens of sales."},
    {date:"August 25, 2026", body:"The <b>1998 Bowman's Best Refractor #27</b> (/400) got its first PSA 10 sale, $3,250. A <b>1998 Stadium Club Triumvirate Luminous #T16B</b> PSA 9 sold for $1,330 in a 52-bid auction. <b>1998 All-Galactic Team #1</b> raw jumped from $631 to <span class='up'>$950</span> (up 51%) on a 40-bid auction."},
    {date:"August 20, 2026", body:"The <b>1998 Topps Chrome Refractor #321</b> led the day, raw climbing from $860 to <span class='up'>$1,451</span> (up 69%) on a 22-bid auction. The <b>1998 Topps Gallery of Heroes #GH1</b> pulled back hard in PSA 10, from $2,500 to <span class='down'>$675</span> (down 73%). A PSA 8 <b>1998 Ultra Gold Medallion #1G</b> debuted at $510 in a 47-bid auction &mdash; the card's biggest crowd yet."},
    {date:"August 16, 2026", body:"<b>1998 Topps Gallery of Heroes #GH1</b> PSA 10 climbed from $1,400 to <span class='up'>$2,500</span> (up 79%) on a single sale. <b>1998 Ultra Gold Medallion #1G</b> backed that up with real depth &mdash; four separate sales landed between $255 and $355, pushing the tracked raw price from $225 to <span class='up'>$355</span> (up 58%). <b>1998 Metal Universe Hardball Galaxy</b> PSA 8 jumped from $55 to <span class='up'>$240</span> (up 336%), now within range of its own PSA 9 mark."},
    {date:"August 7, 2026", body:"A PSA 10 <b>1998 Bowman Chrome International Refractor #33</b> sold for <span class='up'>$4,000</span>, up from $1,600 (up 150%) &mdash; a new high for the card. <b>1998 Leaf Fractal Materials #156</b> pulled back hard, with raw dropping from $275 to <span class='down'>$68</span> (down 75%) on a 7-bid auction. <b>1998 Ultra Diamond Immortals</b> raw climbed from $900 to <span class='up'>$1,400</span> (up 56%)."},
    {date:"August 3, 2026", body:"A raw <b>1998 Fleer Ultra Gold Medallion #1G</b> sold for <span class='up'>$225</span>, up from $165. <b>1998 Metal Universe Diamond Heroes</b> PSA 9 climbed from $465 to <span class='up'>$550</span>. <b>1998 Stadium Club Royal Court #1</b> got its first PSA 9 sale at <span class='up'>$676</span>, well above its $85 raw mark."},
    {date:"July 29, 2026", body:"A PSA 9 <b>1998 Metal Universe Base #161</b> sold for <span class='up'>$450</span>, up from $212 (up 112%). <b>1998 Hardball Galaxy</b> PSA 9 climbed from $200 to <span class='up'>$350</span> (up 75%), and <b>1998 Universal Language</b> PSA 10 moved from $300 to <span class='up'>$347</span>."},
    {date:"July 26, 2026", body:"The <b>1998 Metal Universe All-Galactic Team</b> raw price jumped from $225 to <span class='up'>$900</span> (up 300%), one of the sharpest moves of the year on this card. The <b>1998 Stadium Club Triumvirate Luminescent</b> raw corrected the other way, from $449 to <span class='down'>$80</span>, and the <b>1998 Upper Deck Piece of the Action</b> jersey card eased from $618 to <span class='down'>$399.95</span>."},
    {date:"July 25, 2026", body:"The <b>1998 Finest The Man #TM1 (/500)</b> had a monster stretch across both graded tiers &mdash; PSA 8 jumped from $1,300 to <span class='up'>$2,093</span> on a 48-bid auction, and PSA 9 followed with a freshly-graded sale at <span class='up'>$3,200</span> (44 bids), up from $2,175. Both are new highs for this insert."},
    {date:"July 22, 2026", body:"A <b>1998 Donruss Crusade Red #39</b> &mdash; 1 of just 25 &mdash; sold for <span class='up'>$16,223</span> in PSA 7, and the <b>1998 Topps Chrome Refractor #321</b> PSA 10 brought <span class='up'>$6,223</span> at auction. The <b>1998 Donruss Preferred Prized Collections</b> PSA 8 jumped from $206 to <span class='up'>$1,314</span> (/55, 28 bids) and the <b>1998 Topps Finest Centurion</b> raw firmed from $143 to <span class='up'>$210</span>. The <b>1998 Stadium Club Royal Court #1</b> raw climbed from $61 to <span class='up'>$130</span> and the <b>1998 Circa Thunder Rave Reviews</b> PSA 8 from $201 to <span class='up'>$304</span>."},
    {date:"July 19, 2026", body:"A 34-bid auction pushed the <b>1998 Topps Chrome Refractor #321</b> PSA 10 from $4,150 to <span class='up'>$6,223</span> (up 50%), a new high and the top '98 sale of the day. The base <b>1998 Topps #321</b> PSA 10 also climbed, from $138 to <span class='up'>$216</span> (up 57%) with 18 bids. Raw prices firmed across Metal Universe: <b>1998 All-Galactic Team</b> from $221 to <span class='up'>$800</span> (up 262%), <b>1998 Titanium</b> from $275 to <span class='up'>$316</span> in a 39-bid auction, and <b>1998 Diamond Heroes</b> from $45 to <span class='up'>$86</span> with 23 bids, alongside a PSA 8 at $130. <b>1998 Ultra Gold Medallion</b> raw rose from $160 to <span class='up'>$225</span>, <b>1998 Diamond Producers</b> raw from $275 to <span class='up'>$299</span>, and <b>1998 Topps Gallery of Heroes #GH1</b> raw from $550 to <span class='up'>$638</span>. The <b>1998 Topps Mystery Finest Bordered Refractor #M20</b> PSA 8 climbed from $90 to <span class='up'>$200</span> (up 122%). A raw <b>1998 Donruss Elite Master Craftsmen /100</b> sold for $1,009, a <b>1998 SPx Finite Radiance /1,000</b> raw for $124, and a <b>1998 Topps Inter-League Mystery Finest Refractor #ILM10</b> raw for $90. Cooling: <b>1998 Finest Centurion /500</b> raw from $170 to <span class='down'>$143</span> at auction, and <b>1998 Flair Showcase Row 1 #1</b> raw from $271 to <span class='down'>$175</span> (down 35%). Lower down, the base <b>1998 Metal Universe #161</b> had a PSA 8 sell at $66, <b>1998 E-X2001 #10</b> raw firmed from $35 to <span class='up'>$42</span> in a 16-bid auction, and <b>1998 Topps Lords of the Diamond #LD1</b> raw eased from $40 to <span class='down'>$35</span>."},
    {date:"July 14, 2026", body:"The <b>1998 Ultra Gold Medallion</b> PSA 9 pushed from $950 to <span class='up'>$1,225</span> (up 29%), though its raw eased from $179 to <span class='down'>$160</span>. A PSA 8 <b>1998 Finest Refractor #100</b> sold for <span class='up'>$309</span> in a 24-bid auction. <b>1998 Topps Lords of the Diamond #LD1</b> raw ticked up from $35 to <span class='up'>$40</span>. Softening: <b>1998 Topps Chrome Flashback Refractor #FB2</b> raw from $230 to <span class='down'>$140</span> (down 39%), and <b>1998 Metal Universe Hardball Galaxy</b> gave back more of its recent run — raw from $19 to <span class='down'>$16</span> and PSA 8 from $60 to <span class='down'>$55</span> across a stack of sales."},
    {date:"July 12, 2026", body:"A PSA 8 <b>1998 Topps Chrome Refractor #321</b> sold for <span class='up'>$1,600</span>, between the raw at $860 and the PSA 9 at $2,500. The <b>1998 Topps Gallery of Heroes #GH1</b> raw rose from $355 to <span class='up'>$550</span>, and <b>1998 Metal Universe Hardball Galaxy</b> PSA 8 climbed from $50 to <span class='up'>$60</span>. The base <b>1998 Topps Chrome #321</b> had a PSA 9 sell at $105. Corrections underneath: <b>1998 Stadium Club Royal Court #1</b> raw from $104 to <span class='down'>$61</span> at auction, <b>1998 Metal Universe Diamond Heroes</b> raw from $75 to <span class='down'>$45</span> on three sales, and <b>1998 Hardball Galaxy</b> raw from $25 to <span class='down'>$19</span>. Added the <b>1998 Pinnacle Performers Big Bang #1 (/2,500)</b> at raw $44."},
    {date:"July 10, 2026", body:"A 27-bid auction moved the <b>1998 Finest Non-Protected Refractor</b> PSA 9 from $230 to <span class='up'>$609</span> — closing the gap on its PSA 10 at $1,150. <b>1998 E-X2001 #10</b> cooled at both ends: PSA 9 from $355 to <span class='down'>$338</span> in a 30-bid auction, raw from $73 to <span class='down'>$38</span> on back-to-back auctions. <b>1998 Zenith Z-Team Gold</b> got its first raw price at $73 after an 18-bid auction, and <b>1998 Metal Universe Hardball Galaxy</b> its first PSA 8 at $50. <b>1998 Finest Centurion /500</b> raw ticked up from $165 to <span class='up'>$170</span>, while <b>1998 Topps Lords of the Diamond</b> raw slipped from $40 to <span class='down'>$35</span> and <b>1998 Pinnacle Epix</b> raw from $63 to <span class='down'>$28</span>."},
    {date:"July 8, 2026", body:"First PSA 9 data on the <b>1998 Stadium Club Triumvirate Luminescent</b> landed at <span class='up'>$1,780</span>, and the <b>1998 Ultra Win Now</b> acetate got its first PSA 9 at <span class='up'>$300</span>. <b>1998 Leaf Fractal Materials /250</b> raw ticked up to <span class='up'>$207</span> at auction with 18 bids, and <b>1998 Metal Universe Universal Language</b> PSA 10 reached a new high at <span class='up'>$300</span>. Corrections: <b>1998 Fleer Tradition Zone #7</b> raw eased from $240 to <span class='down'>$203</span>, <b>1998 Finest Centurion</b> raw to <span class='down'>$165</span>, and <b>1998 Diamond Heroes</b> raw to <span class='down'>$75</span>."},
    {date:"July 4, 2026", body:"The <b>1998 Finest Centurion /500</b> told two stories at once today, and both were corrections. The raw price had been parked at $898 on ancient data — a real sale just dragged it down to <span class='down'>$180</span>. Meanwhile the PSA 8 went the other way, climbing from $127 to <span class='up'>$214</span> on two sales in a single day. Translation: the old raw number was fantasy, and the graded market is where the real demand lives. The <b>1998 Bowman Chrome Refractor #33</b> PSA 9 jumped from $300 to <span class='up'>$425</span> — '98 Bowman Chrome keeps tracking upward grade by grade. And the <b>1998 Circa Thunder Rave Reviews</b>, a 1:288 die-cut that almost never surfaces raw, finally landed its first ungraded price: <span class='up'>$515</span> at auction with 25 bids. Even the base is moving — <b>1998 Metal Universe #161</b> PSA 9 ticked up to <span class='up'>$212</span>. The only cooler note: the <b>1998 Mirror Image Fusion Refractor /100</b> PSA 9 eased from $2,200 to <span class='down'>$2,048</span>, which on a /100 card is less a decline than a rounding error."},
    {date:"June 29, 2026", body:"The <b>1998 Leaf Rookies & Stars Longevity /50</b> PSA 9 sat at null for months because almost nothing trades. Only 50 copies exist. When a PSA 9 finally surfaced at <span class='up'>$1,900</span>, the math made immediate sense — PSA 8 was already at $1,009, so the 9 at $1,900 is actually a tight grade premium for a card this scarce. That's how thinly-held cards work: the first sale in months sets the new benchmark. Elsewhere, the <b>1998 Metal Universe Diamond Heroes</b> raw continues grinding — 24 bids at $85 is real demand, not a one-off. Added two new entries today: <b>1998 SPx Finite Radiance /1000</b> PSA 8 at $80, and <b>1998 Topps Tek Pattern 29</b> PSA 9 at $132, a card that barely comes up because most collectors don't realize Tek had different patterns that are worth dramatically different amounts."},
    {date:"June 27, 2026", body:"<b>1998 Ultra Diamond Immortals</b> PSA 9 sold for <span class='up'>$2,700</span> at auction with 38 bids — first PSA 9 data and a monster number. Raw also surged from $514 to <span class='up'>$900</span>. <b>1998 Platinum Portraits</b> raw up from $213 to <span class='up'>$260</span>. <b>1998 Hardball Galaxy</b> raw climbed from $19 to <span class='up'>$30</span>. Filled in <b>1998 Diamond Heroes</b> raw at $70, <b>1998 Mystery Finest Bordered Refractor</b> raw at $120, <b>1998 Milestone Refractor</b> PSA 8 at $106, and <b>1998 Masterstrokes</b> raw at $41. Lots of blanks filled today — the collection tracker is getting more useful by the hour."},
    {date:"June 25, 2026", body:"<b>1998 Finest Centurion (/500)</b> raw landed at <span class='up'>$898</span> at auction with 27 bids — first raw data on this card. <b>1998 Diamond Heroes</b> PSA 9 ticked up from $450 to <span class='up'>$465</span>. <b>1998 Metal Universe Titanium</b> raw eased from $384 to <span class='down'>$320</span>."},
    {date:"June 24, 2026", body:"Active sales but prices held — All-Galactic Team PSA 8 confirmed at $1,500 and Diamond Heroes PSA 9 at $450. The Crusade Red aftershock has settled."},
    {date:"June 23, 2026", body:"<b>1998 Donruss Crusade Red (/25)</b> PSA 8 sold for <span class='up'>$32,433</span> at auction with 52 bids. That's now the most expensive card in this entire guide — 25 copies exist on earth. Added to the database today. <b>1998 All-Galactic Team</b> PSA 8 surged again from $830 to <span class='up'>$1,500</span> — this card has moved from $750 to $1,500 in three days. <b>1998 Diamond Heroes</b> PSA 9 up from $375 to <span class='up'>$450</span>. <b>1998 Fleer Tradition Zone</b> PSA 8 up from $250 to <span class='up'>$288</span>. 1998 Metal Universe is the hottest corner of the Griffey market right now."},
    {date:"June 22, 2026", body:"<b>1998 Metal Universe Hardball Galaxy</b> filled in PSA 9 at $200 — a sci-fi design that's becoming increasingly collectible. The rest of '98 held steady today."},
    {date:"June 21, 2026", body:"<b>1998 Metal Universe All-Galactic Team</b> PSA 8 moved from $750 to <span class='up'>$830</span>. At 1:192 packs, this insert continues to climb. The rest of '98 held steady — <b>1998 Donruss Elite Prime Numbers</b> had a PSA 9 sell at $335 but with only 4 bids and potential variant confusion (#1B vs die-cut), leaving the existing $800 in place for now."}
  ],
  1999: [
    {date:"September 24, 2026", body:"The <b>1999 Topps Chrome Fortune 15 #FF5</b> PSA 10 more than doubled, $270 to <span class='up'>$585</span> &mdash; the first sale of that card in the gem tier since July, and it landed well clear of where the raw copies have been trading. <b>1999 Bowman's Best Franchise Best Mach I #FB2</b> raw went from $70 to <span class='up'>$186</span> on a 36-bid auction, the most contested '99 card of the week. <b>1999 Topps Lords of the Diamond #LD1</b> was the busiest card in the run with eleven raw sales spread from $60 to $202.50; the average pulled the price up from $72 to <span class='up'>$95</span>, and the $202.50 copy took 30 bids to get there."},
    {date:"September 20, 2026", body:"A PSA 10 of the <b>1999 Stadium Club Triumvirate Illuminator #T13B</b> sold for <span class='up'>$3,500</span>, up from $1,075 (up 226%), more than five times what the #T3B Illuminator brings in the same grade. The <b>1999 Skybox Thunder Turbocharged #3</b> split both ways: PSA 10 climbed from $755 to <span class='up'>$1,550</span> (up 105%) while a 22-bid auction took the raw card from $191 to <span class='down'>$114</span>. <b>1999 Topps Chrome All-Etch Refractor #AE3</b> PSA 9 moved from $752 to <span class='up'>$1,052</span> in a 25-bid auction, while the plain All-Etch #AE3 was the busiest 1999 card of the week with seven raw sales settling at $47."},
    {date:"September 13, 2026", body:"A PSA 10 of the <b>1999 Upper Deck Black Diamond Triple #76</b> sold for <span class='up'>$5,100</span> after 36 bids, more than the Quadruple, numbered to 56, brings in PSA 9. The <b>1999 Topps Chrome Lords of the Diamond Refractor #LD1</b> kept climbing, PSA 8 from $550 to <span class='up'>$731</span> (up 33%) on a 39-bid auction and PSA 9 from $2,200 to <span class='up'>$2,400</span>, while the plain Topps <b>Lords of the Diamond #LD1</b>, the most-traded card of the week with 13 raw sales, eased from $84 to <span class='down'>$70</span>. <b>1999 Skybox Molten Metal Xplosion #133</b> PSA 10 moved from $522 to <span class='up'>$811</span> (up 55%) in a 38-bid auction."},
    {date:"September 8, 2026", body:"The <b>1999 Metal Universe Planet Metal #13</b> PSA 9 climbed from $295 to <span class='up'>$1,950</span> (up 561%) in a 23-bid auction; the same card brings $888 in PSA 8 and $4,888 in PSA 10. A <b>1999 Fleer Ultra Diamond Producers #1</b> drew 56 bids and sold ungraded for <span class='up'>$919</span>, up from $400 (up 130%). A PSA 10 of the <b>1999 Topps Tek Gold</b>, serial-numbered to 10, sold for <span class='up'>$5,000</span>."},
    {date:"September 2, 2026", body:"<b>1999 Skybox Thunder Hip-No-Tized #4</b> PSA 9 more than tripled, from $255 to <span class='up'>$825</span>, and <b>1999 Bowman's Best Base #80</b> PSA 10 jumped from $65 to <span class='up'>$200</span>. The base <b>1999 Topps Lords of the Diamond #LD1</b> PSA 9 climbed from $175 to <span class='up'>$450</span>, while its Topps Chrome Refractor sibling firmed from $1,250 to <span class='up'>$2,200</span> in PSA 9 &mdash; big moves on thin data, worth watching for confirmation. <b>1999 Finest Double Feature Refractor #DF1</b> (w/ A-Rod) PSA 9 went the other way, giving back over half its value from $180 to <span class='down'>$83</span>."},
    {date:"August 25, 2026", body:"<b>1999 Linchpins #4</b> raw more than doubled from $1,500 to <span class='up'>$2,938</span> (up 96%) on a 40-bid auction, one of the most contested sales in the guide this month. <b>1999 Record Numbers Refractor #RN4</b> moved on both ends of its ladder — raw from $404 to <span class='up'>$950</span> and PSA 9 from $625 to <span class='up'>$1,000</span>. <b>1999 Bowman's Best Refractor #86</b> (/400) PSA 9 climbed from $1,256 to <span class='up'>$1,575</span> (up 25%) on a 23-bid auction."},
    {date:"August 20, 2026", body:"The <b>1999 Topps Chrome Fortune 15 Refractor (/100)</b> debuted at $35,000 in PSA 10 &mdash; the highest price in the guide, topping the previous record of $20,000 on the <b>1999 Finest Gold Refractor #200</b>. The <b>1999 Lords of the Diamond Refractor #LD1</b> wasn't far behind: PSA 10 climbed from $1,576 to <span class='up'>$8,000</span> (up 408%), with raw, PSA 8, and PSA 9 all moving up too. <b>1999 Skybox Molten Metal Fusion #33F</b> also surged, raw more than doubling from $1,400 to <span class='up'>$3,150</span> (up 125%)."},
    {date:"August 16, 2026", body:"<b>1999 Skybox Molten Metal Fusion Sterling (/500)</b> PSA 8 shot from $1,660 to <span class='up'>$6,878</span> (up 314%) on a 32-bid auction &mdash; serious contested demand for a card already five figures in PSA 10. A <b>1999 Topps Finest Gold Refractor #200</b> PSA 8 sold for <span class='up'>$5,250</span>, sliding neatly between the card's $3,405 raw and $7,100 PSA 9 on this /100 print run. <b>1999 Metal Universe Planet Metal</b> PSA 8 climbed from $385 to <span class='up'>$908</span> (up 136%) after a 38-bid auction, its biggest jump yet."},
    {date:"August 7, 2026", body:"A PSA 9 <b>1999 Ultra Thunderclap #10</b> sold for <span class='up'>$2,600</span>, up from $1,100 (up 136%) &mdash; the card's biggest sale yet. <b>1999 Topps Gallery Gallery of Heroes #GH3</b> PSA 10 jumped from $810 to <span class='up'>$1,350</span> (up 67%). <b>1999 Stadium Club One of a Kind (/150)</b> saw its first sale, a raw copy at $744."},
    {date:"August 3, 2026", body:"<b>1999 Skybox Molten Metal Fusion Sterling (/500)</b> raw jumped from $2,250 to <span class='up'>$4,299</span> (up 91%). <b>1999 Skybox Premium Soul of the Game</b> PSA 8 climbed from $710 to <span class='up'>$1,150</span> (up 62%). On the downside, <b>1999 SP Signature Edition Sample #1</b> PSA 10 eased from $316 to <span class='down'>$210</span>."},
    {date:"July 29, 2026", body:"A PSA 8 <b>1999 Skybox Premium Soul of the Game</b> sold for <span class='up'>$710</span>, up from $149 (up 377%). <b>1999 Metal Universe Diamond Soul</b> raw climbed from $675 to <span class='up'>$800</span>, and <b>1999 Planet Metal</b> raw moved from $333 to <span class='up'>$405</span>."},
    {date:"July 26, 2026", body:"The <b>1999 Flair Showcase Row 2 (Passion)</b> PSA 8 rocketed from $35 to <span class='up'>$190</span> (up 443%). The <b>1999 Topps Chrome All-Etch #AE3</b> PSA 10 also jumped hard, from $155 to <span class='up'>$499.99</span>, and the <b>1999 Fleer Brilliants Shining Stars</b> raw price climbed from $40 to <span class='up'>$78.50</span> on a cluster of sales. <b>1999 Bowman's Best Franchise Best Mach I</b> raw rose from $29 to <span class='up'>$65</span>, while <b>1999 Skybox Thunder Turbocharged</b> raw eased from $185 to <span class='down'>$155</span>."},
    {date:"July 25, 2026", body:"A freshly-graded <b>1999 Metal Universe Linchpins #4</b> PSA 8 brought a stunning <span class='up'>$5,338</span> on 37 bids &mdash; oddly above the card's own PSA 9 price, likely a hype-driven auction rather than a new baseline. <b>1999 Metal Universe Diamond Soul</b> jumped hard on both fronts: raw from $590 to <span class='up'>$675</span> and PSA 8 from $98 to <span class='up'>$850</span> (Pop 34). <b>1999 Skybox Premium Soul of the Game</b> PSA 9 pushed from $1,500 to <span class='up'>$1,999</span>, and <b>1999 Finest Prominent Figures Refractor #PF44</b> PSA 9 nearly doubled from $136 to <span class='up'>$270</span>. <b>1999 Upper Deck Ovation Standing Ovation #1</b> PSA 8 more than doubled from $143 to <span class='up'>$332</span> in a 28-bid auction. <b>1999 Skybox Thunder Turbocharged #3</b> raw climbed from $123 to <span class='up'>$185</span>, <b>1999 UD Choice Starquest Red</b> PSA 8 from $70 to <span class='up'>$130</span>, and <b>1999 Ultra Gold Medallion #72G</b> raw from $22 to <span class='up'>$58</span>. One correction: <b>1999 Skybox Molten Metal Xplosion #133</b> raw dropped from $350 to <span class='down'>$70</span> &mdash; the old raw price looks to have been stale relative to its own PSA 9 ($242)."},
    {date:"July 22, 2026", body:"The <b>1999 Skybox Molten Metal Fusion #33F</b> PSA 9 climbed from $3,200 to <span class='up'>$4,000</span> on multiple sales, and the <b>1999 Skybox Premium Soul of the Game</b> PSA 9 from $1,100 to <span class='up'>$1,500</span>. The <b>1999 Stadium Club Chrome Refractor #SCC20</b> PSA 9 jumped from $398 to <span class='up'>$749</span> and the <b>1999 Topps Chrome Lords of the Diamond Refractor #LD1</b> PSA 9 from $400 to <span class='up'>$600</span>. Raw prices firmed too &mdash; <b>1999 Metal Universe Planet Metal</b> from $265 to <span class='up'>$333</span> and <b>1999 Skybox Thunder Turbocharged #3</b> from $100 to <span class='up'>$123</span>."},
    {date:"July 19, 2026", body:"Graded inserts led 1999. The <b>1999 Molten Metal Xplosion #133</b> PSA 9 jumped from $51 to <span class='up'>$242</span> (up 375%) in a 31-bid auction, and the <b>1999 Topps Chrome All-Etch Refractor #AE3</b> PSA 9 climbed from $475 to <span class='up'>$800</span> (up 68%). The <b>1999 Bowman Chrome Refractor #52</b> PSA 9 rose from $650 to <span class='up'>$799</span> with 28 bids, and the <b>1999 Upper Deck Game Jersey #KG-H</b> PSA 9 from $760 to <span class='up'>$886</span> in a 24-bid auction. The <b>1999 Topps Chrome Lords of the Diamond Refractor #LD1</b> PSA 8 moved from $330 to <span class='up'>$450</span>, with raw copies from $338 to <span class='up'>$350</span>. Raw prices firmed on the scarce inserts: <b>1999 Metal Universe Diamond Soul</b> from $431 to <span class='up'>$590</span> (up 37%), <b>1999 Skybox Premium Soul of the Game</b> from $300 to <span class='up'>$366</span> in a 21-bid auction, and <b>1999 Topps Gallery Gallery of Heroes #GH3</b> from $175 to <span class='up'>$220</span>. A <b>1999 Bowman Chrome Diamond Aces Refractor #DA11</b> raw sold for $216 after a 34-bid auction, a <b>1999 Skybox Thunder Hip-No-Tized #4</b> raw for $144, and the <b>1999 Bowman's Best Franchise Best Mach III /500</b> sold at $400 raw and $1,000 in PSA 9. Cooling: <b>1999 Ultra Thunder Clap #10</b> raw from $325 to <span class='down'>$260</span> and <b>1999 Stadium Club Video Replay #VR3</b> PSA 10 from $134 to <span class='down'>$127</span>."},
    {date:"July 14, 2026", body:"The <b>1999 Skybox Premium Soul of the Game #9</b> PSA 9 climbed from $950 to <span class='up'>$1,100</span> (up 16%). A raw <b>1999 Bowman's Best Refractor /400</b> sold for <span class='up'>$1,025</span> in a 14-bid auction. <b>1999 Ultra Thunderclap #10</b> raw moved from $280 to <span class='up'>$325</span>, <b>1999 Ultra base #72</b> PSA 9 from $13 to <span class='up'>$30</span>, and <b>1999 Fleer Brilliants Shining Stars #1</b> raw from $35 to <span class='up'>$38</span>. On the other side, <b>1999 Skybox Thunder Turbocharged #3</b> raw fell from $140 to <span class='down'>$100</span> (down 29%) at auction and <b>1999 Topps Chrome All-Etch #AE3</b> raw from $61 to <span class='down'>$46</span>."},
    {date:"July 12, 2026", body:"The <b>1999 Metal Universe Linchpins #4</b>, one of the scarcest die-cuts in the set, had a raw copy sell for <span class='up'>$2,374</span>. The <b>1999 Topps Chrome Lords of the Diamond Refractor #LD1</b> raw climbed from $286 to <span class='up'>$338</span> in a 4-bid auction, <b>1999 Metal Universe Planet Metal</b> raw from $250 to <span class='up'>$265</span>, and <b>1999 E-X Century base #17</b> raw from $49 to <span class='up'>$55</span>. A <b>1999 Topps Gallery Player's Private Issue /250</b> raw sold for $100 and an <b>1999 Ultra Gold Medallion #72G</b> raw for $22. The non-refractor <b>1999 Topps Chrome Lords of the Diamond #LD1</b> gave back its spike, from $103 to <span class='down'>$38</span> on two sales, and a group of commons softened: <b>1999 UD Choice Starquest Red</b> from $52 to <span class='down'>$30</span>, <b>1999 Finest Peel &amp; Reveal Sparkle</b> from $62 to <span class='down'>$50</span>, and <b>1999 Flair Showcase Row 3 #3</b> from $50 to <span class='down'>$20</span>."},
    {date:"July 10, 2026", body:"<b>1999 Team Finest Gold /250</b> got its first raw price at <span class='up'>$500</span>. The <b>1999 E-X Century #17</b> PSA 9 jumped from $100 to <span class='up'>$225</span> — with a single PSA 10 in the pop report, the 9 is the top of this card's ladder. Triumvirate was strong across tiers: first raw data on the <b>1999 Illuminator #T13B</b> at $352 after a 20-bid auction, and <b>1999 Luminous #T3B</b> up at both ends — PSA 8 from $65 to <span class='up'>$71</span>, raw from $44 to <span class='up'>$62</span>. <b>1999 Stadium Club #200</b> PSA 10 rose from $100 to <span class='up'>$135</span>, <b>1999 Standing Ovation #81</b> PSA 8 from $129 to <span class='up'>$160</span>, <b>1999 Damage Inc. #8</b> raw from $40 to <span class='up'>$55</span>, and <b>1999 UD Choice StarQuest Red</b> raw doubled from $25 to <span class='up'>$52</span> in a 17-bid auction. <b>1999 Topps Chrome Lords of the Diamond Refractor</b> raw came back to earth, from $425 to <span class='down'>$286</span> on two sales, and <b>1999 Finest Prominent Figures /457</b> raw debuted at $128."},
    {date:"July 8, 2026", body:"<b>1999 Skybox Thunder Dial 1 #3D</b> PSA 10 doubled from $1,350 to <span class='up'>$2,700</span> — a 1:300 pull that rarely trades in gem. <b>1999 Molten Metal Xplosion #133</b> PSA 10 nearly tripled from $185 to <span class='up'>$522</span> at auction with 31 bids, and <b>1999 Topps Chrome All-Etch Refractor</b> raw climbed to <span class='up'>$545</span>. <b>1999 Skybox Thunder Turbocharged #3</b> raw dropped from $1,524 to <span class='down'>$140</span>. <b>1999 Flair Showcase Measure of Greatness /500</b> filled in raw at $400 with PSA 8 up to <span class='up'>$490</span>, <b>1999 Bowman Chrome Diamond Aces Refractor</b> PSA 9 rose to <span class='up'>$400</span>, and <b>1999 UD View to a Thrill Double</b> PSA 9 jumped from $77 to <span class='up'>$219</span>."},
    {date:"July 4, 2026", body:"When the same card sells for $3,900 and $3,850 on back-to-back days, that's not a fluke — that's a new floor. The <b>1999 Topps Chrome All-Etch Refractor</b> PSA 10 jumped from $2,800 to <span class='up'>$3,875</span> on twin sales, cementing it as one of the elite '99 Chrome cards in gem. The <b>1999 Skybox Premium Soul of the Game</b> got a full repricing top to bottom: two PSA 9 sales on the same day ($1,200 and $700) moved the grade from $400 to <span class='up'>$950</span>, while three raw sales pushed ungraded copies from $170 to <span class='up'>$267</span>. That card was a $65 raw afterthought two weeks ago. <b>1999 Skybox Thunder In Depth</b> PSA 10 climbed from $340 to <span class='up'>$550</span>, <b>1999 Gallery of Heroes #GH3</b> PSA 9 rose to <span class='up'>$318</span>, and the <b>1999 Metal Universe Diamond Soul</b> — the card that stunned everyone with a $1,000 PSA 9 last week — filled in its raw price at <span class='up'>$431</span> on 32 bids. One eyebrow-raiser to watch: a <b>1999 Molten Metal Xplosion</b> raw sold for <span class='up'>$350</span>, well above its own PSA 10 at $185. Either someone knows something about that low pop count, or someone overpaid. The sold listings will settle the argument soon enough."},
    {date:"June 29, 2026", body:"The <b>1999 Finest Gold Refractor /100</b> raw just crossed $3,400 — 19 bids and no hesitation. Only 100 were made and each auction moves the price ceiling because there's no supply pressure keeping it down. It's up $600 in a single session. The <b>1999 Metal Universe Diamond Soul</b> PSA 9 filling in at <span class='up'>$1,000</span> is equally notable — a card most collectors couldn't even name that's been hiding in a $4,000+ PSA 10 all along. One PSA 9 sale rewrites the whole story. And the <b>1999 Topps Chrome Lords of Diamond</b> non-refractor raw going from $20 to <span class='up'>$103</span> with 22 bids is the kind of move that makes you question every null in the database. 1999 keeps delivering surprises for collectors who actually look at the sold listings instead of assuming they know what things are worth."},
    {date:"June 27, 2026", body:"Blank-fill day across 1999. <b>1999 Gallery of Heroes</b> raw climbed from $134 to <span class='up'>$203</span> at auction. <b>1999 EX Century</b> raw up from $30 to <span class='up'>$45</span>. Filled in <b>1999 Bowman Chrome Lasting Impact Refractor</b> raw at $300, <b>1999 All-Topps Mystery Finest Refractor</b> raw at $175, <b>1999 Topps Chrome All-Etch</b> raw at $61, <b>1999 Ionix Cyber</b> raw at $45, <b>1999 Brilliants Shining Stars</b> raw at $35, <b>1999 Stadium Club Chrome</b> raw at $30, and <b>1999 Starquest Red</b> raw at $25. On the downside, <b>1999 Topps Lords of the Diamond</b> raw dropped from $46 to <span class='down'>$21</span> and <b>1999 Finest Milestone Refractor</b> PSA 9 fell from $130 to <span class='down'>$73</span>. Massive session for filling portfolio-ready cells."},
    {date:"June 26, 2026", body:"<b>1999 Molten Metal Fusion</b> PSA 9 more than doubled from $1,450 to <span class='up'>$3,200</span> — the non-Sterling Fusion is now a $3K card in a 9. <b>1999 Thunderclap</b> raw surged from $175 to <span class='up'>$410</span>. <b>1999 Lords of the Diamond Refractor</b> raw doubled from $210 to <span class='up'>$425</span>. <b>1999 Planet Metal</b> filled in raw at $225. The 1999 Skybox/Fleer inserts continue their run — everything scarce is getting repriced."},
    {date:"June 25, 2026", body:"<b>1999 Skybox Thunder Turbocharged</b> raw exploded from $50 to <span class='up'>$1,524</span> at auction with 39 bids — a 30x move that rewrites the book on this card. <b>1999 Molten Metal Fusion Sterling</b> (/500) raw landed at <span class='up'>$2,250</span>. <b>1999 Soul of the Game</b> raw nearly tripled from $65 to <span class='up'>$170</span>. The rare Skybox inserts from '99 are being discovered and repriced in real time."},
    {date:"June 24, 2026", body:"<b>1999 Video Replay #VR3</b> gaining momentum — PSA 9 up from $26 to <span class='up'>$33</span>, PSA 10 from $103 to <span class='up'>$134</span>. <b>1999 Triumvirate Luminescent #T3B</b> PSA 8 softened from $250 to <span class='down'>$200</span>. Lots of confirmations across the board today — most prices holding from yesterday's updates."},
    {date:"June 23, 2026", body:"PSA 8 prices climbing across the board. <b>1999 Planet Metal</b> PSA 8 moved from $256 to <span class='up'>$340</span>. <b>1999 Lords of the Diamond Refractor</b> PSA 8 jumped from $240 to <span class='up'>$359</span>. <b>1999 Black Diamond Single</b> PSA 10 nearly doubled from $109 to <span class='up'>$204</span>. <b>1999 Triumvirate Luminous #T13B</b> PSA 8 up from $62 to <span class='up'>$91</span>. Added <b>1999 Finest Team Finest Gold</b> (/250) PSA 9 at $600 and <b>1999 Finest Double Feature Refractor</b> (w/ A-Rod) PSA 10 at $175. The PSA 8 grade is where the action is in '99 right now."},
    {date:"June 22, 2026", body:"<b>1999 Topps Chrome All-Etch Refractor #AE3</b> PSA 8 jumped from $260 to <span class='up'>$350</span> — demand is climbing across all grades on this card. Added <b>1999 Finest Prominent Figures Refractor</b> (/457) PSA 10 at $750 and <b>1999 Topps Tek Gold</b> (/10) PSA 9 at $676 — a POP 1 sale with 20 bids."},
    {date:"June 21, 2026", body:"<b>1999 Topps Chrome Early Road to Hall Refractor</b> (/100) just got its first PSA 10 sale — <span class='up'>$10,000</span> at auction with 45 bids. At 1:944 packs, this is now the second most valuable card in all of 1999. <b>1999 Bowman's Best Atomic Refractor</b> (/100) filled in PSA 8 at $1,875 with 30 bids. Planet Metal PSA 7 hit $250 at auction with 38 bids — that card is hot in every grade."}
  ]
};
